local E = ns.DB.entries
E["npc:dendrite-starblaze"] = {t="npc",n="Dendrite Starblaze",z="moonglade",s="In Nighthaven, Dendrite Starblaze guides druids who come to Moonglade. As a Cenarion Circle mentor, he welcomes night elf and tauren apprentices. Through him they are summoned to the holy grove to master its rites, from cleansing toxins to communing with nature's forms.",h="In Nighthaven, Dendrite Starblaze guides druids who come to Moonglade.",sec={{t="A Guide in the Sacred Haven",b="When novice druids learn Teleport: Moonglade, Dendrite is among the first to greet them in Nighthaven. He follows the Cenarion Circle's calling beyond the Alliance and Horde. Night elf and tauren druids alike find kinship beneath the haven's boughs, where Kaldorei tradition meets the tauren path.",sp=0},{t="Trials of the Wild",b="Dendrite guides apprentices into nature's deeper ways. He sends them to examine tainted waters and seek herbs that can cure poison and pestilence. Then he oversees the water trials, testing their patience and endurance beneath the surface before he grants them communion with aquatic forms.",sp=0}},faq={{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is a night elf druid and Cenarion Circle mentor in Nighthaven, within Moonglade. He guides developing druids through essential rites and training.",al={"dendrite starblaze","who is dendrite","starblaze moonglade"},it="identity"},{q="Why does a night elf train Horde tauren?",a="The Cenarion Circle keeps beyond the Alliance and Horde's political divisions. In Moonglade, night elves and tauren practice druidic arts together under ancient oaths of brotherhood, leaving worldly conflicts beyond the mountain passes.",al={"why does dendrite train horde","dendrite tauren druid","cross faction druid mentor"},it="side"},{q="What quests does Dendrite Starblaze offer?",a="Dendrite guides druids through trials in curing venom and disease, then toward the communion required for aquatic form.",al={"dendrite quests","starblaze quest list"},gp=true},{q="Where can Dendrite Starblaze be found?",a="Dendrite can be found in Nighthaven, on the northern shores of Lake Elune'ara in Moonglade.",al={"dendrite location","where is starblaze","dendrite starblaze map"},it="place",gp=true},{q="How do young druids reach Dendrite for the first time?",a="Racial trainers teach novice druids Teleport: Moonglade around their tenth circle of training. The spell carries them straight to Moonglade, where Dendrite awaits.",al={"how to get to dendrite","teleport to moonglade quest"},it="arrival",gp=true},{q="Can non-druid adventurers interact with him?",a="Non-druids may visit Nighthaven and speak with Dendrite. He offers no training, trials or tasks to those outside the Cenarion Circle's druidic traditions.",al={"non druid dendrite","can warrior talk to starblaze"},gp=true},{q="What does Dendrite Starblaze want?",a="Dendrite guides novice druids along the path of nature and balance. Through trials honoring the spirits of the wild—such as communing with the Great Bear Spirit and mastering powers over poison and the waters—he works to ensure that all initiates, regardless of their heritage, learn the responsibilities and ancient disciplines of the Cenarion Circle.",al={"dendrite starblaze goal","what does dendrite want","dendrite starblaze motive"},it="wants",add="3038adca"},{q="Why is Dendrite Starblaze in Moonglade?",a="Moonglade is sacred, neutral ground where the Cenarion Circle convenes away from worldly factional conflict. Stationed in Nighthaven, Dendrite serves as a welcoming mentor for fledgling druids summoned to the haven, administering foundational lessons and trials essential to their spiritual growth.",al={"why is dendrite here","dendrite starblaze location moonglade","why is dendrite in nighthaven"},it="why_here",add="ef589fff"},{q="Who is Dendrite Starblaze tied to?",a="Dendrite is an emissary and mentor within the Cenarion Circle. He works closely with fellow druids of both night elf and tauren lineage, answering the call of the wild spirits and the teachings of Cenarius rather than the political banners of Darnassus or the Horde.",al={"dendrite starblaze faction","dendrite starblaze cenarion circle","who does dendrite serve"},it="ties",add="7aee8496"}},ang={["class:Druid"]="When you first teleport to Moonglade, Dendrite guides you in curing sickness and seeking communion with aquatic forms.",["race:Tauren"]="As a Shu'halo druid from Mulgore, you can see in Dendrite how the Cenarion Circle's bond reaches beyond the feud between Horde and Alliance.",["race:NightElf"]="As a Kaldorei initiate, you meet Dendrite at Nighthaven, where he keeps the classical rites of nature stewardship and welcomes you into the Cenarion order."},kw={"aquatic form","cenarion circle","curing the sick","dendrite starblaze","druid","lessons anew","moonglade","night elf","nighthaven"},rel={"subzone:nighthaven","quest:5921","quest:6121","quest:6124","quest:6125","quest:31","quest:5932","quest:5931"},src={"Dendrite Starblaze"}}
E["npc:loganaar"] = {t="npc",n="Loganaar",z="moonglade",s="In Nighthaven, Loganaar guides druids from both factions in the ways of their calling. He teaches them to heed nature and prepares them for the Emerald Dream.",h="In Nighthaven, Loganaar guides druids from both factions in the ways of their calling.",sec={{t="Keeper of the Sacred Art",b="Loganaar welcomes newly initiated druids who come to Moonglade from Darnassus or Thunder Bluff. In Nighthaven, he teaches balance, shape-shifting, and reverence for nature. Even in cold stone or unfamiliar lands, he says, tranquility must come from within. He also leads promising students toward deeper Cenarion Circle concerns.\n\nSome druids he sends to wanderers such as Torwa Pathfinder in Un'Goro Crater. Others he guides into ancient woodland rites.",sp=0},{t="The Call of the Dream",b="Loganaar teaches that Kalimdor's traditional protectors share a deeper calling: the Emerald Dream. He speaks of the sacred bond between Azeroth's primal spirit realm and the waking world. To master their path, druids must hibernate for centuries and walk among nature's purest forms, guided by the demigods.",sp=0}},faq={{q="Who is Loganaar?",a="Loganaar guides druids in Nighthaven, Moonglade's central settlement. He welcomes druids from every background and introduces them to the Cenarion Circle's deeper traditions.",al={"loganaar npc","who is loganaar","loganaar lore"}},{q="Does Loganaar train Horde druids?",a="Yes. Loganaar teaches both tauren and night elf druids. As a member of the Cenarion Circle, he sets aside the conflict between the Alliance and Horde on Moonglade's sacred, neutral ground.",al={"can tauren train at loganaar","loganaar horde","druid trainer moonglade horde"}},{q="What does Loganaar teach about the Emerald Dream?",a="Loganaar teaches that every true druid feels the Emerald Dream's pull. He says a long, deep hibernation lets druids walk among its uncorrupted forms, where their ultimate training takes place.",al={"loganaar dream","emerald dream quote"}},{q="Where does Loganaar send seasoned druids?",a="Loganaar sends seasoned druids to observe and mend Azeroth's primal ecosystems. He directs some to help naturalists such as Torwa Pathfinder in the wilderness of Un'Goro Crater.",al={"loganaar quests","torwa pathfinder quest loganaar"}}},ang={["class:Druid"]="As a druid of Darnassus or Thunder Bluff, you meet Loganaar early after teleporting to Moonglade. He offers advanced training and spiritual counsel.",["race:NightElf"]="As a night elf, you share the Kaldorei druids' ancient traditions. For millennia, they communed with nature and entered the Emerald Dream under Malfurion Stormrage."},kw={"cenarion circle","druid trainer","emerald dream","loganaar","moonglade","nighthaven"},rel={"subzone:nighthaven","zone:moonglade","topic:druid","topic:emerald-dream","npc:torwa-pathfinder","topic:cenarius","topic:night-elf"},src={"Loganaar"}}
E["npc:remulos"] = {t="npc",n="Remulos",z="moonglade",s="In Moonglade, Keeper Remulos guides the druids of the Cenarion Circle. Cenarius has fallen and Malfurion Stormrage sleeps, so Remulos helps lead the Circle. He puts nature’s balance before night elven isolation.",h="In Moonglade, Keeper Remulos guides the druids of the Cenarion Circle.",sec={{t="Lord of the Sacred Grove",b="Keeper Remulos watches over Moonglade, the druids’ sacred sanctuary north of Mount Hyjal. Immortal, he bears the lower body of a great stag and the antlered torso of an ancient dryad-father. His divine authority and counsel aid the Cenarion Circle while Malfurion Stormrage remains trapped in the Emerald Dream. He works to heal Azeroth’s scars and aids druids in their sacred rites around Lake Elune'ara.",sp=0},{t="A Rift in the Circle",b="Keeper Remulos often clashes with Archdruid Fandral Staghelm over the Circle’s path. Staghelm champions night elven supremacy and sought to restore his people’s lost immortality by planting Teldrassil. Remulos opposed the new World Tree, seeing its planting as hubris.\n\nRemulos also defied Staghelm’s isolationist faction by welcoming Hamuul Runetotem and the tauren into the Cenarion Circle. There, their shamans-turned-druids could learn nature’s closely guarded mysteries and help restore the land alongside others.",sp=0}},faq={{q="Who is Keeper Remulos?",a="Keeper Remulos is an immortal son of Cenarius and brother to the fallen Zaetar. He lives in the Shrine of Remulos in Moonglade, guards the grove, and is a senior leader of the Cenarion Circle.",al={"remulos lore","who is remulos","keeper remulos background"}},{q="Why does Remulos support the tauren druids?",a="Remulos believes nature’s balance reaches beyond mortal racial divides. He recognized the tauren’s deep bond with the Earth Mother and welcomed Archdruid Hamuul Runetotem and his people into the Cenarion Circle despite Archdruid Fandral Staghelm’s objections.",al={"remulos tauren","why do tauren have druids","remulos hamuul"}},{q="What is Remulos's opinion on Teldrassil?",a="Remulos vehemently opposed the creation of Teldrassil. He saw the planting of the new World Tree as a selfish attempt by night elves to reclaim their lost immortality, not a true effort to heal Azeroth.",al={"remulos world tree","remulos fandral tree"}},{q="What relation does Remulos have to Maraudon?",a="Remulos’s brother Zaetar ventured into Desolace and mated with Princess Theradras, becoming the father of the centaur before his death. Remulos warned Zaetar against the union, and Maraudon holds his brother’s legacy and that of the centaur.",al={"remulos zaetar","remulos theradras","remulos brother"},sp=1}},ang={["class:Druid"]="Whether night elf or tauren, every druid journeys to Moonglade to meet Keeper Remulos and seek guidance in mastering animal forms and sacred trials.",["race:Tauren"]="As a tauren druid, you can revere Remulos for defying Fandral Staghelm and welcoming your people into the Cenarion Circle, where they received full teaching."},kw={"cenarion circle","cenarius","fandral staghelm","grove","hamuul runetotem","moonglade","remulos","zaetar"},rel={"topic:cenarion-circle","topic:cenarius","zone:moonglade","npc:fandral-staghelm","quest:1489","npc:malfurion-stormrage","subzone:lake-elune-ara","topic:druid"},src={"Keeper Remulos"}}
E["quest:272"] = {t="quest",n="Trial of the Sea Lion",z="moonglade",s="Druids in Moonglade seek the sea lion’s spirit through a sacred rite. They recover two scattered pendant halves for agility and endurance, then unite them at the Shrine of Remulos to prepare for Aquatic Form.",h="Druids in Moonglade seek the sea lion’s spirit through a sacred rite.",sec={{t="The Path to Aquatic Form",b="Druid initiates in Moonglade undergo trials of attunement as they prepare to navigate Azeroth’s deep waters. The Trial of the Sea Lion follows earlier preparations in their spiritual training. Dendrite Starblaze oversees it in Nighthaven, where initiates learn to balance the sea lion’s graceful speed with its resilient stamina. Both are needed to take its form and withstand the ocean depths.",sp=0},{t="Agility and Endurance",b="The trial centers on reuniting the two halves of the Pendant of the Sea Lion. One represents the sea lion’s agility as it glides through turbulent currents. The other represents its endurance, the fortitude to dive long into freezing water without faltering. Initiates seek guidance from Moonglade’s inhabitants as they search across the world for the scattered relics.",sp=0},{t="The Shrine of Remulos",b="Once both halves are found, the initiate brings them near the Shrine of Remulos, where they can be joined into one talisman. The shrine’s energies bind agility and endurance in harmony. The initiate then presents the restored pendant to Dendrite Starblaze in Nighthaven. With the pendant, the druid shows readiness to embrace the sea lion aspect and awaken Aquatic Form.",sp=0}},faq={{q="What is the Trial of the Sea Lion?",a="Druids in Moonglade recover two pendant halves and unite them at the Shrine of Remulos. The halves represent agility and endurance, and the restored pendant is presented to Dendrite Starblaze as part of the path to Aquatic Form.",al={"trial of the sea lion quest","what is trial of the sea lion","sea lion trial"}},{q="Who gives the Trial of the Sea Lion quest?",a="Warden Tajarri at the Shrine of Remulos in Moonglade gives the trial. Initiates seek guidance from local residents, join the pendant halves near the shrine, then take the finished pendant to Dendrite Starblaze in Nighthaven.",al={"who gives trial of the sea lion","where to start trial of the sea lion","trial of the sea lion quest giver"}},{q="What do the two pendant halves represent?",a="The halves represent the sea lion’s agility and endurance. One reflects the grace and swiftness to glide through deep water; the other, the stamina and resilience for long journeys underwater. Druids must respect and embody both traits equally to master their shapeshifting arts.",al={"what are the pendant halves","pendant halves meaning","agility and endurance halves"}},{q="Where are the pendant halves located?",a="Initiates learn where the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance are hidden by speaking with Moonglade’s residents. Local druids and villagers give clues about the distant waters where each half was lost or concealed.",al={"how to find pendant halves","where to find the pendant halves","pendant of the sea lion halves location"}},{q="Where do you assemble the Pendant of the Sea Lion?",a="The halves must be joined near the Shrine of Remulos in Moonglade. The shrine’s sacred aura helps unite agility and endurance in one talisman.",al={"how to combine pendant halves","where to fuse pendant halves","where is shrine of remulos pendant"}},{q="Why must druids balance agility and endurance?",a="Dendrite Starblaze teaches that agility and endurance must be balanced beneath the water. Speed without stamina brings exhaustion, while endurance without swiftness leaves a swimmer helpless against strong currents. Druids need both traits to embody the sea lion’s spirit.",al={"why agility and endurance","sea lion traits druid","meaning of the sea lion trial"}},{q="What is gained by completing the trial?",a="Completing the trial earns the restored Pendant of the Sea Lion and fulfills a major trial required to earn Aquatic Form. Mastering agility and endurance gives the initiate a spiritual foundation for taking a form that can breathe and swim swiftly underwater.",al={"what do you get from trial of the sea lion","sea lion trial reward","does this give aquatic form"}}},ang={["class:Druid"]="This rite is exclusive to druids. It tests their spiritual maturity and balance before they may commune with aquatic spirits and adopt the sea lion’s form.",["race:NightElf"]="As long-standing custodians of Moonglade and the Cenarion Circle, night elf druids revere Dendrite Starblaze’s teachings and the sacred ground around the Shrine of Remulos.",["race:Tauren"]="For tauren druids newly welcomed into the Cenarion Circle, undertaking the trial in Moonglade strengthens their communion with nature spirits and deepens their ties with their night elf mentors."},kw={"aquatic form","dendrite starblaze","half pendant of aquatic agility","half pendant of aquatic endurance","moonglade","nighthaven","pendant of the sea lion","shrine of remulos","trial of the sea lion"},rel={"item:pendant-of-the-sea-lion","npc:dendrite-starblaze","quest:31","npc:remulos","subzone:nighthaven","quest:5921"},m={faction="Alliance",cl={"DRUID"},ra={"NightElf"},id=272},src={"In-game quest text: Trial of the Sea Lion"},fv=true}
E["quest:28"] = {t="quest",n="Trial of the Lake",z="moonglade",s="Tajarri awaits the result of a trial at the Shrine of Remulos in Moonglade. A Shrine Bauble from Lake Elune'ara is at its heart.",h="Tajarri awaits the result of a trial at the Shrine of Remulos in Moonglade.",sec={{t="At the Shrine",b="At the Shrine of Remulos in northwestern Moonglade, Tajarri asks you to complete a trial. Find a Shrine Bauble in Lake Elune'ara and bring it to the shrine. Use it there, then speak with Tajarri to complete the trial.",sp=0}},faq={{q="What does Tajarri ask me to do?",a="Tajarri asks you to find a Shrine Bauble in Lake Elune'ara, use it at the Shrine of Remulos, then speak with Tajarri.",al={"tajarri trial","what do i need","lake trial"}},{q="Where is the Shrine of Remulos?",a="The Shrine of Remulos is in northwestern Moonglade.",al={"remulos shrine location","where's the shrine","shrine location"}},{q="Where do I find the Shrine Bauble?",a="The Shrine Bauble is in Lake Elune'ara.",al={"bauble location","find bauble","lake bauble"}},{q="What do I do with the Shrine Bauble?",a="Take the Shrine Bauble to the Shrine of Remulos and use it there.",al={"use bauble","bauble at shrine","shrine bauble"}},{q="Who do I speak with after using the bauble?",a="Speak with Tajarri at the shrine after using the Shrine Bauble.",al={"talk to tajarri","after the shrine","finish trial"}}},kw={"lake elune'ara","moonglade","shrine bauble","shrine of remulos","tajarri","trial of the lake"},rel={"quest:5921","subzone:lake-elune-ara","npc:remulos"},m={faction="Horde",cl={"DRUID"},ra={"Tauren"},id=28},src={"In-game quest text: Trial of the Lake"},fv=true}
E["quest:29"] = {t="quest",n="Trial of the Lake",z="moonglade",s="In Moonglade, an initiate faces the Trial of the Lake, a timed test of speed and dexterity. You dive into Lake Elune'ara for an unstable Shrine Bauble, then hurry to the Shrine of Remulos before it decays. Success earns Tajarri's recognition and honors the Cenarion Circle's devotion to balance.",h="In Moonglade, an initiate faces the Trial of the Lake, a timed test of speed and dexterity.",sec={{t="A Test of Dexterity",b="Moonglade's guardians oversee this rite for initiates. You dive into Lake Elune'ara to find a delicate Shrine Bauble resting along the sunken lakebed. It begins to decay as soon as you disturb it, so you need a sure touch, keen senses, and swift movement to carry it overland before its magic fades.",sp=0},{t="Tribute to the Keeper",b="Once you have the bauble, you must hurry to the Shrine of Remulos in northwestern Moonglade. The monument honors Keeper Remulos, who guides the Cenarion Circle in preserving nature and world balance. Activating the bauble there marks its importance to the Circle. Warden Tajarri greets initiates who beat the time limit and the competition.",sp=0}},faq={{q="What is the Trial of the Lake?",a="The Trial of the Lake tests an initiate's agility and focus in Moonglade. You dive into the cold depths of Lake Elune'ara to retrieve a Shrine Bauble that decays rapidly, then race across the haven to the Shrine of Remulos before its energy dissipates.",al={"what is trial of the lake","purpose of trial of the lake","what is this quest"}},{q="Where is the Shrine of Remulos located?",a="The Shrine of Remulos stands in northwestern Moonglade. It honors Keeper Remulos, who guides the Cenarion Circle, and warden Tajarri guards and maintains it.",al={"where is shrine of remulos","shrine location","remulos shrine moonglade"}},{q="Who is Tajarri?",a="Tajarri is a trusted warden of Moonglade who tends the Shrine of Remulos. She oversees the Trial of the Lake and welcomes initiates who bring the bauble to honor the shrine.",al={"who is tajarri","tajarri moonglade","shrine warden tajarri"}},{q="What is a Shrine Bauble?",a="A Shrine Bauble is a relic found along the bed of Lake Elune'ara. Once taken from the water, it decays rapidly, so its bearer must race to activate it at the Shrine of Remulos as tribute before its energy dissipates.",al={"what is shrine bauble","why does bauble decay","shrine bauble purpose"}},{q="Why is Keeper Remulos honored at this shrine?",a="Keeper Remulos is a revered keeper of the grove who guides the Cenarion Circle in preserving nature and maintaining balance. The shrine in northwestern Moonglade honors his leadership and principles.",al={"who is keeper remulos","remulos lore","why honor remulos"}},{q="What does offering the bauble at the shrine signify?",a="Activating the bauble at the Shrine of Remulos pays tribute to the sacred balance the Cenarion Circle maintains and acknowledges the shrine's lasting spiritual importance in Moonglade.",al={"what does using bauble do","why activate bauble at shrine"}}},ang={["class:Druid"]="As a druid, you face a test of swiftness and adaptability in Moonglade. The rite of passage honors Keeper Remulos."},kw={"cenarion circle","lake elune'ara","moonglade","remulos","shrine bauble","shrine of remulos","tajarri","trial of the lake"},rel={"subzone:lake-elune-ara","npc:remulos","topic:cenarion-circle","quest:5921","topic:elune"},m={faction="Alliance",cl={"DRUID"},ra={"NightElf"},id=29},src={"In-game quest text: Trial of the Lake"},fv=true}
E["quest:30"] = {t="quest",n="Trial of the Sea Lion",z="moonglade",s="Tajarri asks you to seek two pendant halves in Moonglade and bring the joined Pendant of the Sea Lion to Dendrite Starblaze. Clues from the residents point toward the halves, and the Shrine of Remulos is where they can be joined.",h="Tajarri asks you to seek two pendant halves in Moonglade and bring the joined Pendant of the Sea Lion to...",sec={{t="Tajarri's Request",b="Tajarri at the Shrine of Remulos asks you to find two halves of a pendant in Moonglade. The residents may know where the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance can be found. Bring the joined Pendant of the Sea Lion to Dendrite Starblaze in Nighthaven.",sp=0},{t="At the Shrine",b="The two pendant halves can be joined near the Shrine of Remulos. Once formed, the Pendant of the Sea Lion is to be brought to Dendrite Starblaze in Nighthaven.",sp=0}},faq={{q="What does Dendrite Starblaze want?",a="Dendrite Starblaze waits in Nighthaven for the joined Pendant of the Sea Lion. Tajarri sends you to find the two pendant halves in Moonglade and join them near the Shrine of Remulos.",al={"dendrite request","what does dendrite need"}},{q="Where can I find clues about the pendant halves?",a="The residents of Moonglade may have clues about where the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance are located.",al={"pendant clues","where are the halves"}},{q="Where do I join the two halves?",a="The two pendant halves can be joined in proximity to the Shrine of Remulos.",al={"join pendant","shrine pendant"}},{q="Where is Dendrite Starblaze waiting?",a="Dendrite Starblaze is in the village of Nighthaven in Moonglade.",al={"dendrite location","where is dendrite"}}},kw={"aquatic agility","aquatic endurance","dendrite starblaze","moonglade","nighthaven","pendant","sea lion","shrine of remulos","trial of the sea lion"},rel={"quest:5921","subzone:nighthaven","npc:dendrite-starblaze","npc:remulos","item:pendant-of-the-sea-lion"},m={faction="Horde",cl={"DRUID"},id=30},src={"In-game quest text: Trial of the Sea Lion"},fv=true}
E["quest:31"] = {t="quest",n="Aquatic Form",z="moonglade",s="In Thunder Bluff, a young Horde druid returns to be recognized among the keepers of nature. The druid has proved worthy in Moonglade and taken on the sea lion aspect; now formal recognition brings Aquatic Form.",h="In Thunder Bluff, a young Horde druid returns to be recognized among the keepers of nature.",sec={{t="Return of the Sea Lion",b="Dendrite Starblaze sends you back to Mulgore after your trials in Moonglade. The Pendant of the Sea Lion bears proof of your balance and dedication across Kalimdor's waters. By carrying it home, you show that you have honored the ancient traditions needed to take an aquatic aspect.",sp=0},{t="Communion with the Waters",b="At Thunder Bluff's heights, you bring the pendant to Turak Runetotem, your mentor. He is pleased that you have honored your ancestors and kept nature in balance. Then Turak teaches you the secret of aquatic form. You can swim beneath rivers and oceans, breathe freely, and find your way through the depths as a sea creature.",sp=0}},faq={{q="What is the purpose of this quest?",a="This rite completes a young Horde druid's passage. In Thunder Bluff, you present the Pendant of the Sea Lion and learn Aquatic Form.",al={"why do this quest","aquatic form purpose","what does this quest do"},it="purpose"},{q="Who do I bring the Pendant of the Sea Lion to?",a="Bring the Pendant of the Sea Lion to Turak Runetotem, the druid trainer on Thunder Bluff's upper rises in Mulgore.",al={"who turns this in","where to turn in aquatic form","turak runetotem location"},it="next_step",gp=true},{q="Who sends you back to Thunder Bluff?",a="Dendrite Starblaze sends you back after your aquatic trials in Moonglade are complete.",al={"who gives aquatic form quest","dendrite starblaze quest"},it="origin",gp=true},{q="Can non-druids complete this quest?",a="No. Only druids can complete this rite and advance along their spiritual and magical path toward animal forms.",al={"is this druid only","can other classes do aquatic form"},gp=true},{q="Why does a night elf in Moonglade help a Horde druid?",a="Moonglade is a neutral sanctuary overseen by the Cenarion Circle. Night elf mentors guide tauren druids in the ancient Cenarion arts, seeking balance in nature without political hostility.",al={"why does dendrite help horde","moonglade horde alliance","druid neutrality"},it="why_here"},{q="What ability does completing this quest grant?",a="Turak Runetotem teaches you Aquatic Form. In this shape, you swim faster and breathe underwater.",al={"what form do i get","aquatic form spell","water form"},it="power",gp=true},{q="Why does Dendrite Starblaze send you back to Thunder Bluff?",a="Dendrite Starblaze oversees your trials in Moonglade on behalf of the Cenarion Circle, but Moonglade is a sanctuary of instruction rather than your personal home. Having tested your endurance and reverence for the water, Dendrite's duty is complete. He directs you back to your local mentor, Turak Runetotem on the Elder Rise of Thunder Bluff, to present proof of your rites and receive the final blessing that grants you the aquatic form.",al={"why send to turak","dendrite starblaze motive","why return to thunder bluff"},it="motive",add="269933c9"}},ang={["class:Druid"]="As a druid, Aquatic Form helps you cross bodies of water with ease and escape predators in the deep.",["race:Tauren"]="As a tauren, mastering the beasts of the sea honors your ancestors and strengthens your people's return to druidic ways.",["faction:Horde"]="As a member of the Horde, you share the tauren druids' spiritual link to the Cenarion Circle, walking between neutral sanctuaries and tribal capitals."},kw={"aquatic form","dendrite starblaze","druid","moonglade","pendant of the sea lion","sea lion","thunder bluff","turak runetotem"},rel={"npc:turak-runetotem","npc:dendrite-starblaze","topic:druid","zone:thunderbluff","quest:5921","quest:1067"},m={start="Dendrite Starblaze",["end"]="Turak Runetotem",level="16",faction="Horde",cl={"DRUID"},ra={"Tauren"},id=31},src={"Aquatic Form (Horde)"}}
E["quest:5061"] = {t="quest",n="Aquatic Form",z="moonglade",s="You bring the restored Pendant of the Sea Lion back to Darnassus. The rite teaches Alliance druids to attune their spirits to deep waters.",h="You bring the restored Pendant of the Sea Lion back to Darnassus.",sec={{t="A Sacred Bond with the Depths",b="For Cenarion Circle initiates, shapeshifting binds a druid’s spirit to the wild aspects of Azeroth. Young night elf druids endure trials in the dark coastal depths and in Moonglade. There, Dendrite Starblaze gives them the assembled Pendant of the Sea Lion. They carry this sacred token back to Teldrassil, proof of their respect for the laws of air, water, and breath.",sp=0},{t="Return to Darnassus",b="Mathrengyl Bearwalker awaits your return in the Cenarion Enclave. Your trials along the coasts of Darkshore and Westfall have tested your endurance and attunement. Present the completed pendant to show Bearwalker that your mind and body are ready to shed their mortal skin. Then you can take the swift, breathing form of the sea lion.",sp=0}},faq={{q="What is the purpose of this quest?",a="Presenting the restored Pendant of the Sea Lion to Mathrengyl Bearwalker in Darnassus completes an Alliance druid’s training in Aquatic Form. The pendant proves you are ready to learn this aquatic shape.",al={"why do this quest","aquatic form purpose","what does this quest give"},it="purpose"},{q="Who sends you back to Darnassus?",a="Dendrite Starblaze sends you from Moonglade back to Teldrassil after you complete the Trial of the Sea Lion. Starblaze is an elder of the Cenarion Circle.",al={"who gives this quest","quest giver","dendrite starblaze"},it="identity"},{q="Who completes your training in Darnassus?",a="Mathrengyl Bearwalker receives your pendant in Darnassus’s Cenarion Enclave and teaches you the aquatic aspect. He is the druid trainer there.",al={"quest hand in","who turns in aquatic form","mathrengyl bearwalker"},it="identity"},{q="What is the Pendant of the Sea Lion?",a="The Pendant of the Sea Lion is a sacred talisman made by joining two trial pendants recovered from watery depths off Darkshore and Westfall. It proves a druid has mastered the endurance and patience required of sea creatures.",al={"what is the pendant","pendant of the sea lion lore"},it="item"},{q="Do Horde druids do this exact quest?",a="No. Tauren druids also face trials in Moonglade to earn their aquatic aspect. Then they return to Turak Runetotem on the mesas of Thunder Bluff instead of Darnassus.",al={"can tauren do this","is this quest alliance only","horde version"},gp=true},{q="Where in Darnassus is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is in the Cenarion Enclave, in Darnassus’s northwestern district atop the boughs of Teldrassil.",al={"where is mathrengyl","darnassus druid trainer location"},it="place",gp=true},{q="Why does Dendrite Starblaze send you back to Darnassus?",a="Dendrite Starblaze has guided you through the sacred trials of Moonglade, but it is the duty of your local mentor, Mathrengyl Bearwalker, to bestow the final lessons. By returning with the assembled Pendant of the Sea Lion, you provide proof of your readiness and discipline, allowing Mathrengyl to complete your training and grant you mastery over the aquatic aspect.",al={"why does dendrite send you back","dendrite starblaze motive","why go back to darnassus"},it="motive",add="d3754c26"}},ang={["class:Druid"]="As a druid, this rite marks a step in your communion with nature. Aquatic Form lets you move swiftly underwater and breathe beneath the surface without end.",["race:NightElf"]="As a night elf, you return from Moonglade’s timeless woods to Teldrassil’s youthful crown. This affirms your duty to protect Azeroth’s wilderness amid shifting balance.",["faction:Alliance"]="As an Alliance druid, your trials prepare you to scout lakes, rivers, and coastal shores with ease."},kw={"aquatic form","cenarion enclave","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","pendant of the sea lion","sea lion"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","topic:druid","zone:darnassus","quest:5921","quest:31"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="16",faction="Alliance",cl={"DRUID"},ra={"NightElf"},id=5061},src={"Aquatic Form (Alliance)"}}
E["quest:5929"] = {t="quest",n="Great Bear Spirit",z="moonglade",s="In Moonglade, druids are sent north to seek the Great Bear Spirit. Communion with this ancient guide teaches the bear’s nature and strength, a vital part of a druid’s spiritual and martial training.",h="In Moonglade, druids are sent north to seek the Great Bear Spirit.",sec={{t="The Noble Mentor of Moonglade",b="In northwestern Moonglade, the Great Bear Spirit dwells apart from Nighthaven’s quiet paths. This ancient and noble mentor teaches every initiate who seeks to understand the bear’s nature. Druids have long sought its blessing and wisdom as part of the path of the wild.",sp=0},{t="A Rite of Primal Focus",b="Dendrite Starblaze guides young druids from Nighthaven into the hills to meet the spirit. Communion brings primal wisdom and an awareness of natural strength. When the druids return, Dendrite tests their focus. The encounter gives them raw strength and knowing intent, but they must learn to direct that power in their daily work.",sp=0}},faq={{q="Where can the Great Bear Spirit be found?",a="The Great Bear Spirit dwells in the northwestern wilds of Moonglade, apart from Nighthaven and its settled paths.",al={"where is the bear spirit","find bear spirit moonglade","bear spirit location"}},{q="Who sends druids to seek out the Great Bear Spirit?",a="Dendrite Starblaze, an elder druid in Nighthaven, directs initiates to commune with the spirit as part of their natural training.",al={"who sends you to bear spirit","dendrite starblaze role","quest giver bear spirit"}},{q="What is the Great Bear Spirit?",a="The Great Bear Spirit is a wise and noble guide, tutor, and mentor who teaches practicing druids the primal nature of the bear.",al={"what is the bear spirit","bear spirit lore","who is great bear spirit"}},{q="Why must druids commune with the Great Bear Spirit?",a="Initiates commune with the spirit to learn the bear’s nature and take in its raw strength, resilience, and wisdom before returning to put those qualities to work.",al={"why talk to bear spirit","bear spirit quest purpose","what do you learn from bear spirit"}},{q="What happens after the Great Bear Spirit is satisfied?",a="After communing with the spirit, initiates return to Dendrite Starblaze in Nighthaven. Dendrite recognizes their new understanding and prepares them to focus that power.",al={"what happens after bear spirit","dendrite after spirit","after visiting bear spirit"}},{q="Do all druids need to seek the spirit's wisdom?",a="Every druid must seek the Great Bear Spirit’s counsel. Communion is a fundamental step toward attuning to animal forms and natural power.",al={"do all druids visit bear spirit","is bear spirit mandatory","who visits bear spirit"}}},ang={["class:Druid"]="As a druid, you commune with the Great Bear Spirit to gain natural wisdom and the spiritual grounding needed to take on the bear’s resilience."},kw={"bear form","dendrite starblaze","druid quest","great bear spirit","moonglade","nighthaven"},rel={"npc:dendrite-starblaze","topic:druid","subzone:nighthaven","quest:5921"},m={faction="Alliance",cl={"DRUID"},ra={"NightElf"},id=5929},src={"In-game quest text: Great Bear Spirit"},fv=true}
E["quest:5930"] = {t="quest",n="Great Bear Spirit",z="moonglade",s="In Moonglade, Dendrite Starblaze sends you to the Great Bear Spirit to learn about the bear’s nature. He believes your strength and intent are ready to be focused.",h="In Moonglade, Dendrite Starblaze sends you to the Great Bear Spirit to learn about the bear’s nature.",sec={{t="A Lesson in Bear Nature",b="Dendrite Starblaze waits in Nighthaven, Moonglade, with a lesson in mind. He asks you to seek the Great Bear Spirit in the northwest and learn what it can share about the bear’s nature. When you have finished, return to Dendrite; he sees strength and intent in you, and says you can learn to focus both through the bear’s nature.",sp=0}},faq={{q="Who sends me to the Great Bear Spirit?",a="Dendrite Starblaze in Nighthaven asks you to seek the Great Bear Spirit.",al={"who asks me","Dendrite's request"}},{q="Where is the Great Bear Spirit?",a="The Great Bear Spirit is in northwestern Moonglade.",al={"bear spirit location","where's the spirit"}},{q="What am I meant to learn?",a="Dendrite asks you to learn what the Great Bear Spirit has to share about the nature of the bear.",al={"bear nature lesson","what does the spirit teach"}},{q="Where do I return afterward?",a="After speaking with the Great Bear Spirit, return to Dendrite Starblaze in Nighthaven, Moonglade.",al={"where to go back","return to Dendrite"}}},kw={"bear","dendrite starblaze","great bear spirit","moonglade","nature of the bear","nighthaven"},rel={"quest:5921","subzone:nighthaven","npc:dendrite-starblaze","quest:5929"},m={faction="Horde",cl={"DRUID"},ra={"Tauren"},id=5930},src={"In-game quest text: Great Bear Spirit"},fv=true}
E["quest:5931"] = {t="quest",n="Back to Darnassus",z="moonglade",s="You leave Moonglade after meeting the Great Bear Spirit and return to Darnassus. In the Cenarion Enclave, Mathrengyl Bearwalker awaits to guide your practical shapeshifting trials.",h="You leave Moonglade after meeting the Great Bear Spirit and return to Darnassus.",sec={{t="A Journey Between Sanctuaries",b="Dendrite Starblaze sends you from Nighthaven back to Darnassus after your meeting with the Great Bear Spirit in Moonglade. There, you leave the sanctuary where you communed with the spirit and return to the unsettled world beyond. In Darnassus, local mentors watch over Teldrassil and guide the next stage of your training.",sp=0},{t="The Path of the Claw",b="Mathrengyl Bearwalker waits for you in the Cenarion Enclave, guarding nature as its balance falters. The Great Bear Spirit's blessing is only the first step. Mathrengyl prepares you for trials of body and heart, so you can give physical form to the spirit's fierce ancestral wisdom.",sp=0}},faq={{q="Why do I need to return to Darnassus?",a="Moonglade is where you commune with the Great Bear Spirit, while your mentor, Mathrengyl Bearwalker, waits in Darnassus's Cenarion Enclave. He guides practical tests that help you master your new power.",al={"why return to darnassus","why leave moonglade","where does dendrite send me"},it="purpose"},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a seasoned night elf druid trainer in Darnassus's Cenarion Enclave. He guides young initiates along the Way of the Claw and teaches them to master bear form.",al={"who is mathrengyl","mathrengyl bearwalker lore","bearwalker"},it="identity"},{q="How do I get back to Darnassus from Moonglade?",a="Silva Fil'naveth, the hippogryph master in southwestern Nighthaven, can fly you across the sea to Rut'theran Village. From there, a portal leads up into Darnassus.",al={"how to leave nighthaven","moonglade flight back","silva fil'naveth"},gp=true},{q="What happens after I speak to Mathrengyl?",a="Mathrengyl gives you your first true test of purpose: face Lunaclaw at the Moonkin Stone east of Auberdine in Darkshore. The trial proves whether your body and heart are ready to wield bear form.",al={"next quest after back to darnassus","what comes next"},it="next_step"},{q="What is the Path of the Claw?",a="The Path of the Claw is a druidic tradition that channels the bear's ferocity, resilience, and strength through communion with ancient primal spirits.",al={"path of the claw","druid claw lore"},it="power"},{q="Why does Dendrite mention balance faltering near Darnassus?",a="Teldrassil is young and lacks the Dragon Aspects' blessing, leaving its boughs vulnerable to strange corruptions, furbolg madness, and encroaching darkness. Druids in the Cenarion Enclave fight these threats.",al={"balance faltered darnassus","teldrassil corrupted"},it="threat"},{q="Why does Dendrite Starblaze want me to return to Mathrengyl?",a="Dendrite Starblaze has guided you through your initial communion with the Great Bear Spirit in Moonglade, but Moonglade is a place of sanctuary and study, not practical trial. Mathrengyl Bearwalker originally sent you on this spiritual journey and is charged with overseeing your actual training. Dendrite sends you back so Mathrengyl can test your newfound connection to the bear spirit and guide you through the demanding trials required to walk the Path of the Claw.",al={"why send me back dendrite","dendrite starblaze motive","why return to darnassus dendrite"},it="motive",add="8983e9c4"}},ang={["class:Druid"]="For a young druid, this journey carries you from spiritual communion to the physical practice of shapeshifting.",["race:NightElf"]="As a night elf, you travel between Moonglade, an ancient sanctuary, and Teldrassil, the newly planted World Tree. Your journey joins millennia of kaldorei heritage with your duties today."},kw={"bear spirit","bearwalker","cenarion enclave","darnassus","dendrite","mathrengyl","moonglade","shapeshifting","starblaze"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:cenarion-enclave","subzone:nighthaven","zone:darnassus","topic:druid"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="10",faction="Alliance",cl={"DRUID"},ra={"NightElf"},id=5931},src={"Back to Darnassus"}}
E["quest:5932"] = {t="quest",n="Back to Thunder Bluff",z="moonglade",s="At Elder Rise, Turak Runetotem awaits your return from Moonglade. Dendrite Starblaze sends you home after your communion with the Great Bear Spirit, so your training can continue among your people.",h="At Elder Rise, Turak Runetotem awaits your return from Moonglade.",sec={{t="A Bridged Fellowship",b="In Moonglade, night elf and tauren practitioners of nature magic meet in the Cenarion Circle. There, they set aside the divides between mortal factions. After your communion with the Great Bear Spirit, Dendrite Starblaze sends you back to your people. Night elves often see tauren as fledglings in Cenarius’s formal teachings. Yet Starblaze recognizes the wisdom and balance of Turak Runetotem.",sp=0},{t="Return to the Bluffs",b="You climb to Elder Rise in Thunder Bluff and stand before Turak Runetotem, changed by your rite. Communion with ancient totemic spirits such as the Great Bear Spirit runs deep in tauren culture. Yet the Path of the Claw asks for serious commitment. Your spiritual bond is forged, and Turak prepares you to put your new strength and endurance into practice.",sp=0}},faq={{q="Why was a night elf teaching a tauren in Moonglade?",a="The Cenarion Circle is neutral and devoted to preserving nature. In Moonglade, night elf and tauren practitioners set aside the Horde and Alliance divide, allowing Dendrite Starblaze to guide young tauren druids.",al={"dendrite starblaze horde","why night elf mentor","cenarion circle tauren"},it="ties"},{q="Who is Turak Runetotem?",a="Turak Runetotem is an esteemed tauren druid and one of the Arch Druid’s assistants. He is stationed on Elder Rise in Thunder Bluff, where he trains young tauren in the path of nature and the claw, and links them with the Cenarion Circle.",al={"turak runetotem role","elder rise druid leader"},it="identity"},{q="What did the young druid do right before this quest?",a="Before returning to Mulgore, you traveled to Moonglade to seek the ancient Great Bear Spirit and commune with it. You gained its blessing and learned the spiritual core of bear form.",al={"what came before back to thunder bluff","great bear spirit quest"},it="history"},{q="How do young druids travel back to Thunder Bluff from Moonglade?",a="Bunthen Plainswind offers flight services from southwestern Nighthaven, carrying tauren druids safely back to Thunder Bluff after their rites.",al={"how to get back from moonglade","moonglade flight back"},gp=true},{q="What comes next in the druid's training?",a="After your return, Turak Runetotem sends you to face a physical challenge at the Moonkin Stone, where the Barrens meet Mulgore. There, you prove you can channel the spirit’s strength into beast form.",al={"next druid quest","after back to thunder bluff"},it="next_step"},{q="Why does Dendrite Starblaze call tauren 'young in the ways of Cenarius'?",a="Tauren legends tell of ancient communion with Cenarius at the dawn of the world. Night elves developed and sustained formal Cenarion druidism for over ten thousand years, while tauren only recently renewed structured study within the Cenarion Circle.",al={"are tauren new druids","tauren druid history cenarius"},it="origin"},{q="Why does Dendrite Starblaze send you back to Thunder Bluff?",a="Your initial commune with the Great Bear Spirit in Moonglade was only the opening step of your awakening. Dendrite Starblaze recognizes that applying the lessons of the wild requires hands-on guidance from your own mentor. He entrusts the next phase of your instruction to Turak Runetotem, a tauren druid who walks with deep balance, so you may prove yourself worthy of the bear's enduring strength.",al={"why send to turak","dendrite starblaze motive","why back to thunder bluff"},it="motive",add="9396c536"}},ang={["class:Druid"]="As a druid, your journey links Moonglade with the heights of Thunder Bluff and marks your growth along the Path of the Claw.",["race:Tauren"]="As a tauren, you bring the wisdom of the ancient spirits home to help and protect your tribes across Mulgore.",["faction:Horde"]="As a member of the Horde, you help bring shapeshifting defenders to its ranks on the plains of Kalimdor."},kw={"back to thunder bluff","bear form","dendrite starblaze","elder rise","great bear spirit","moonglade","nighthaven","turak runetotem"},rel={"npc:turak-runetotem","npc:dendrite-starblaze","zone:thunderbluff","subzone:elder-rise","subzone:nighthaven","topic:druid","topic:cenarius","topic:tauren"},m={start="Dendrite Starblaze",["end"]="Turak Runetotem",level="10",faction="Horde",cl={"DRUID"},ra={"Tauren"},id=5932},src={"Back to Thunder Bluff"}}
E["quest:6122"] = {t="quest",n="The Principal Source",z="moonglade",s="At Cliffspring Falls, sick deer have drawn the Cenarion Circle to the water. Dendrite Starblaze sends young druids from Moonglade to gather a sample for Auberdine naturalist Alanndarian Nightsong.",h="At Cliffspring Falls, sick deer have drawn the Cenarion Circle to the water.",sec={{t="A Vital Waterway Corrupted",b="Cliffspring Falls feeds northern Darkshore with fresh water. When deer began to suffer a lingering sickness, the Cenarion Circle looked to the river for its cause. Dendrite Starblaze in Moonglade suspects the water is tainted. He sends novice druids to gather a sample at the cavern mouth beneath the falls.",sp=0},{t="Shadows at the Falls",b="Vicious naga dwell inside Cliffspring River Cave, near the falls' headwaters. Their presence endangers anyone who comes to study the blight. The Cenarion Circle needs a sample from the cave mouth to learn what is making the wilderness sick.",sp=0},{t="A Deeper Malady",b="In Auberdine, Alanndarian Nightsong finds that the water sample confirms the Circle's fears. The corrupted falls are poisoning the riverbanks, yet sick deer have also been seen beyond the water's direct path.\n\nThe sample may help begin an antidote. Alanndarian suspects a wider corruption is spreading through Darkshore's water table.",sp=1}},faq={{q="Why is Cliffspring Falls so important to Darkshore?",a="Cliffspring Falls supplies fresh water to northern Darkshore. Its headwaters feed local streams and rivers, so contamination can spread through the surrounding land and wildlife.",al={"why cliffspring falls matters","cliffspring river importance","darkshore water source"},it="place"},{q="Why are the deer in Darkshore falling ill?",a="The deer drink from Cliffspring Falls and the streams it feeds. The water is tainted at its source, and the pollutant is making woodland creatures sick.",al={"why are deer sick","darkshore sick deer","what poisoned the deer"},it="conflict"},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is an elder druid trainer in Moonglade. He guides young druids, watches for disturbances across Kalimdor, and coordinates the Cenarion Circle's response to natural crises.",al={"dendrite starblaze lore","who gave me this quest","starblaze moonglade"},it="identity"},{q="Who is Alanndarian Nightsong?",a="Alanndarian Nightsong is a night elf naturalist in Auberdine. Concerned by the corruption and suffering wildlife in Darkshore, she asked the Cenarion Circle in Moonglade for help studying the affliction and finding a cure.",al={"who is alanndarian nightsong","nightsong auberdine"},it="identity"},{q="Why are naga at Cliffspring Falls?",a="Naga from the Darkshore coast have moved inland and occupied the cave system behind Cliffspring Falls. Their presence endangers anyone trying to reach the headwaters and investigate the water.",al={"naga in cliffspring cave","why are naga here","cliffspring falls naga"},it="threat"},{q="What ability does this quest help druids learn?",a="The investigation is part of the Power over Poison trial. By studying the wildlife sickness and working with Alanndarian Nightsong on an antidote, druid initiates learn to cure poisons.",al={"what spell does this give","druid poison quest","cure poison chain"},it="power"},{q="Why does Dendrite Starblaze want this done?",a="As an emissary of the Cenarion Circle in Moonglade, Dendrite Starblaze is bound to protect the natural balance of Kalimdor. Alanndarian Nightsong reached out from Auberdine seeking aid against a virulent sickness poisoning Darkshore's wildlife. Dendrite suspects the contamination originates at Cliffspring Falls, the region's main freshwater source, and must confirm its source to help create a cure.",al={"dendrite motive","why does dendrite send me","why investigate cliffspring falls"},it="motive",add="df1ca1a8"},{q="What is the Filled Cliffspring Falls Sampler for?",a="The sampler holds corrupted water drawn directly from the cave mouth at Cliffspring Falls. Delivering it to Alanndarian Nightsong in Auberdine allows her to analyze the precise nature of the poison afflicting Darkshore's wildlife and begin concocting an effective cure.",al={"filled cliffspring falls sampler use","what is the water sample for","why collect cliffspring water"},it="item",add="87aa05d6"},{q="Why does Dendrite Starblaze send you instead of handling it himself?",a="Dendrite serves as a key liaison for the Cenarion Circle in Moonglade, coordinating broader druidic efforts across Kalimdor. Investigating the source and collaborating with Alanndarian on the ground in Darkshore offers an essential field trial for an advancing druid learning to wield power over poison.",al={"why me dendrite","why does dendrite need druids","why send an initiate"},it="why_me",add="00d3706a"}},ang={["class:Druid"]="As a druid, you face the decay at Cliffspring Falls and help prepare remedies. This trial teaches you how to cure poisons in the wild.",["race:NightElf"]="As a night elf of Auberdine, you see Cliffspring Falls' corruption threaten your ancestral forests and the creatures that live there."},kw={"alanndarian nightsong","auberdine","cenarion circle","cliffspring falls","cure poison","darkshore","dendrite starblaze","naga","power over poison"},rel={"quest:6125","npc:dendrite-starblaze","npc:alanndarian-nightsong","subzone:cliffspring-falls","subzone:auberdine","zone:darkshore","topic:cenarion-circle","quest:947"},m={start="Dendrite Starblaze",["end"]="Alanndarian Nightsong",level="14",faction="Alliance",cl={"DRUID"},ra={"NightElf"},id=6122,ri={"Filled Cliffspring Falls Sampler"}},src={"The Principal Source (Alliance)"}}
E["quest:6125"] = {t="quest",n="Power over Poison",z="moonglade",s="In Darnassus, Power over Poison brings a young druid back to finish the Cenarion Circle's trial. It began in Darkshore, where the initiate learned to brew a remedy by hand.",h="In Darnassus, Power over Poison brings a young druid back to finish the Cenarion Circle's trial.",sec={{t="The Student's Humility",b="In Darkshore, Alanndarian Nightsong sends young druids to gather Earthroot and Lunar Fungus by hand. They use them to brew a salve for stricken wildlife. Before teaching the magic that purges toxins, the Cenarion Circle asks initiates to learn the hardship of treating poison without spiritual aid. That work shows them what common folk endure when venom strikes, and why a druid must meet their suffering with care.",sp=0},{t="Return to the Enclave",b="The remedy proves effective in Auberdine, and Starblaze sends the druid across the sea to Darnassus. Mathrengyl Bearwalker waits in the Cenarion Enclave. Pleased by the initiate's grace under pressure, he teaches them to cleanse toxins through nature's power. Yet virulent poisons in the wilds around Auberdine trouble him. They point to an unnatural blight that disturbs the land's balance.",sp=0}},faq={{q="What is the purpose of this quest?",a="The trial prepares a druid to cure poison with magic after first making a salve by hand. From Darkshore, the student returns to Mathrengyl Bearwalker in Darnassus to learn Cure Poison.",al={"why do power over poison","power over poison objective","cure poison quest"},it="purpose"},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is an elder druid at Nighthaven in Moonglade. He guides initiates through spiritual trials that test their patience and dedication to nature, then sends them to their home trainers.",al={"dendrite starblaze role","who gives power over poison"},it="people"},{q="Who is Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker is a master druid trainer in Darnassus's Cenarion Enclave. Beneath Teldrassil's boughs, he trains night elf druids in forms, restorative arts, and the duties of the Cenarion Circle.",al={"mathrengyl bearwalker lore","bearwalker darnassus"},it="people"},{q="Why was the druid required to make a cure by hand first?",a="Dendrite Starblaze teaches druids to understand poison's physical toll and the work of treating it without magic. Gathering ordinary ingredients and tending the sick by hand teaches humility and gratitude for the natural gifts they are about to receive.",al={"why make herbal cure","lesson of power over poison"}},{q="What concerns Mathrengyl about the situation in Auberdine?",a="Mathrengyl finds the lethal toxins in the Darkshore wilds around Auberdine unnatural. Their effects on native wildlife and plants threaten the land's balance and point to a corrupting influence along the coast.",al={"auberdine poison lore","mathrengyl concern"},it="threat"},{q="Why does Dendrite Starblaze send you back to Darnassus?",a="Dendrite Starblaze wants you to finish your rite of passage. Having forced you to gather herbs and cure the sick in Auberdine by hand, he has ensured you appreciate the toil ordinary mortals face when battling venom. Now that you understand the stakes and humility required of a guardian of nature, he sends you back so Mathrengyl Bearwalker can bestow the true druidic spell upon you.",al={"why send to mathrengyl","dendrite starblaze motive","why return to darnassus"},it="motive",add="92345f63"}},ang={["class:Druid"]="As a druid, you begin with humble herbal work before receiving nature's magic to cleanse venom.",["race:NightElf"]="As a night elf, you undertake this trial in the Cenarion Enclave in Darnassus. It reflects Kaldorei reverence for balance and care for their ancient forests."},kw={"auberdine","cenarion enclave","cure poison","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","power over poison"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:cenarion-enclave","zone:darnassus","topic:druid","subzone:auberdine"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="14",faction="Alliance",cl={"DRUID"},ra={"NightElf"},id=6125},src={"Power over Poison (Alliance)"}}
E["quest:6127"] = {t="quest",n="The Principal Source",z="moonglade",s="From Moonglade, Dendrite Starblaze sends Horde druids to Dreadmist Peak for a sample of water. She asks them to carry it to Tonga Runetotem at the Crossroads, where it may explain the poison harming wildlife.",h="From Moonglade, Dendrite Starblaze sends Horde druids to Dreadmist Peak for a sample of water.",sec={{t="A Mountain Tainted",b="Dendrite Starblaze fears the Burning Blade has tainted Dreadmist Peak. The mountain rises northwest of the Crossroads, above the dry northern Barrens. Springs and pools crown its heights, shaping the local weather and moisture. Now a cult devoted to demons has taken hold on the crags, and its foul sorcery may poison the basin.",sp=0},{t="A Plague on the Plains",b="Sick gazelles stumble across the northern savanna, north of the main east-west trail through the Crossroads. Tonga Runetotem seeks help for the local tauren and asks the Cenarion Circle to learn what is poisoning the herd. A water sample from the peak will let him study the sickness and brew an antidote.",sp=0}},faq={{q="Where do I get the water sample for this quest?",a="Draw water from the pool at Dreadmist Peak's summit, northwest of the Crossroads in the Barrens. The Burning Blade gathers there, and Dendrite Starblaze gives you a sampler.",al={"dreadmist peak pool location","where is the water pool","principal source water sample"},it="place",gp=true},{q="Why is the water on Dreadmist Peak so important to the Barrens?",a="Dreadmist Peak's high pools influence local weather and mist. Once the Burning Blade fouls them, poisoned vapor and runoff spread across the plains and sicken wildlife in the northern Barrens.",al={"why dreadmist peak matters","barrens weather pool","dreadmist peak pools"},it="place"},{q="Who is Tonga Runetotem?",a="Tonga Runetotem is a tauren druid at the Crossroads in the Barrens. Alarmed by the strange sickness among local gazelles, he asked the Cenarion Circle in Moonglade to diagnose it and cleanse the land.",al={"who is tonga","tonga runetotem role","crossroads druid"},it="identity"},{q="Who is corrupting the water on the peak?",a="The Burning Blade has corrupted the waters. Its demon-worshiping warlocks and fel practitioners occupy Dreadmist Peak's winding paths and summit.",al={"who tainted the pool","dreadmist cultists","burning blade dreadmist"},it="threat"},{q="What ability does completing this chain teach?",a="The rite of Power over Poison teaches young Horde druids the spiritual and herbal knowledge to cure poisons in the field.",al={"power over poison reward","druid poison cure spell","cure poison quest barrens"},gp=true},{q="Can Alliance druids do this quest?",a="No. The Principal Source sends Horde druids to the Barrens to help Tonga Runetotem. Alliance druids make a similar journey in Darkshore to learn to cleanse poisons.",al={"alliance equivalent","can night elves do principal source","alliance poison quest"},gp=true},{q="Why does Dendrite Starblaze want this done?",a="Tonga Runetotem reached out to the Cenarion Circle in Moonglade seeking aid to halt a spreading malady in the Barrens. Dendrite Starblaze suspects that the demon-worshipping Burning Blade has poisoned the pools atop Dreadmist Peak. Because these high waters influence the region's weather patterns, their corruption threatens the delicate balance of the entire northern Barrens ecosystem.",al={"why does dendrite need this","dendrite starblaze motive","why investigate the water"},it="motive",add="41ffa32f"},{q="What is the Filled Dreadmist Peak Sampler for?",a="The filled sampler holds tainted water taken directly from the peak's highest pool. Tonga Runetotem needs this foul specimen at the Crossroads to analyze the foul toxins infecting the local wildlife, allowing him and the Cenarion Circle to study the pollution and brew an effective cure for the stricken gazelles.",al={"filled dreadmist peak sampler use","what is the water sample for","sampler purpose"},it="item",add="54ce2e01"},{q="Why does Dendrite Starblaze send you instead of going himself?",a="As an elder of the Cenarion Circle residing in sacred Moonglade, Dendrite oversees many matters and relies on promising young druids to serve as the Circle's hands across Kalimdor. Answering Tonga's plea provides an essential lesson in cleansing corruption and mastering natural remedies, testing your ability to heal the land.",al={"why send me","why doesn't dendrite go","why a druid student"},it="why_me",add="2b67a7e4"}},ang={["class:Druid"]="As a druid, you trace corruption to its source and isolate magical toxins before they ruin an ecosystem.",["race:Tauren"]="As a tauren, you help shield the Barrens' gazelle herds from demonic taint. These are ancestral lands of Kalimdor's tribes.",["faction:Horde"]="As a member of the Horde, you help guard the Crossroads, a vital center of Horde life in Kalimdor. Demonic blight threatens trade and survival there."},kw={"barrens","cenarion circle","crossroads","dendrite starblaze","dreadmist peak","power over poison","principal source","sickly gazelle","tonga runetotem"},rel={"quest:6125","npc:dendrite-starblaze","npc:tonga-runetotem","subzone:dreadmist-peak","subzone:crossroads","topic:cenarion-circle","zone:barrens","topic:druid"},m={start="Dendrite Starblaze",["end"]="Tonga Runetotem",level="14",faction="Horde",cl={"DRUID"},ra={"Tauren"},id=6127,ri={"Filled Dreadmist Peak Sampler"}},src={"The Principal Source (Horde)"}}
E["quest:6130"] = {t="quest",n="Power over Poison",z="moonglade",s="At Thunder Bluff, a young Horde druid returns to claim the gift of Cure Poison. The initiate has treated poisoned gazelles near the Crossroads with herbal mixtures and now faces Turak Runetotem on the Elder Rise.",h="At Thunder Bluff, a young Horde druid returns to claim the gift of Cure Poison.",sec={{t="A Lesson in Suffering",b="The Cenarion Circle asks a druid to learn how affliction feels before granting the power to cleanse venom. Dendrite Starblaze sends the novice to the Crossroads, where Tonga Runetotem has them gather ingredients for a salve. By treating the Barrens' poisoned gazelles by hand, without spiritual aid, the druid sees how ordinary creatures struggle against natural and unnatural toxins.",sp=0},{t="Return to the Elder Rise",b="After the trial, Dendrite sends the initiate to Turak Runetotem, the grand druid trainer on Thunder Bluff's Elder Rise. Turak warns that strange, virulent poisons near the Crossroads threaten the plains' natural balance. He commends the initiate's grace under pressure and grants the spiritual art of curing poisons. The living creatures of Kalimdor are now in the initiate's care.",sp=0}},faq={{q="What is the purpose of this quest?",a="The trial teaches a Horde druid to cure venom. After preparing remedies by hand to save suffering gazelles, the initiate returns to Turak Runetotem and learns Cure Poison through druidic communion.",al={"why do power over poison","what does this quest do","druid poison quest purpose"},it="purpose"},{q="Where is Turak Runetotem located?",a="Turak Runetotem lives atop the Elder Rise in Thunder Bluff. He resides in the tent and hollowed roosts where tauren druids commune and train.",al={"turak runetotem location","where is turak","find turak runetotem"},gp=true},{q="Who sends the druid back to Thunder Bluff?",a="Dendrite Starblaze sends the druid back to Thunder Bluff after they heal wildlife near the Crossroads. The night elf druid of the Cenarion Circle is stationed in Moonglade.",al={"who gives power over poison","quest giver","dendrite starblaze"},gp=true},{q="Why did the Cenarion Circle make the druid cure beasts manually first?",a="Dendrite Starblaze teaches the druid to understand the labor and limits of curing venom before wielding spiritual magic. Seeing afflicted creatures struggle teaches empathy and respect for nature's balance.",al={"why cure sick manually","why use salves first","druid poison lesson"},it="motive"},{q="What concerns Turak Runetotem about the Crossroads?",a="Turak warns that unnatural, aggressive venoms are reaching wildlife near the Crossroads. He sees this as a grave disruption to the land's balance that calls for vigilance.",al={"turak crossroads concern","crossroads poison balance"},it="threat"},{q="Is this quest available to Alliance druids?",a="Alliance druids take a parallel trial of the same name. Night elf initiates return to Mathrengyl Bearwalker in Darnassus instead of Turak Runetotem on the Elder Rise.",al={"can night elves do this","alliance power over poison"},gp=true}},ang={["class:Druid"]="As a druid, you join physical herbalism in Kalimdor with nature magic and gain the lasting power to purge toxins from allies.",["race:Tauren"]="As a tauren, you prove your dedication to the Cenarion Circle and keep the Earth Mother's wisdom alive on the Elder Rise.",["faction:Horde"]="As a member of the Horde, you help safeguard central Kalimdor's wild lands from unnatural corruption."},kw={"barrens","crossroads","cure poison","dendrite starblaze","elder rise","moonglade","thunder bluff","turak runetotem"},rel={"npc:turak-runetotem","npc:dendrite-starblaze","subzone:elder-rise","zone:thunderbluff","topic:druid","subzone:crossroads","quest:6125"},m={start="Dendrite Starblaze",["end"]="Turak Runetotem",level="14",faction="Horde",cl={"DRUID"},ra={"Tauren"},id=6130},src={"Power over Poison (Horde)"}}
E["quest:98341"] = {t="quest",n="The Great Windborne Cat Spirit",z="moonglade",s="In Moonglade, the Avatar of Saeyleenan guides young shen'dorei druids through a spiritual trial. The spirit comes from Zephras and helps them embody the windborne feline form of their homeland.",h="In Moonglade, the Avatar of Saeyleenan guides young shen'dorei druids through a spiritual trial.",sec={{t="A Visitor from Zephras",b="South of Moonglade's twin bridges, a spirit from distant Zephras has appeared in the sacred sanctuary. Calling itself the Avatar of Saeyleenan, this windborne cat spirit has crossed into Azeroth to guide young shen'dorei druids ready to unlock their feline form.",sp=0},{t="The Nature of the Windborne Form",b="Druids seek wisdom in the feline form, but those from Zephras follow a different tradition from Azeroth's native peoples. The shen'dorei embody the windborne predator of their homeland instead of an Azerothian wildcat. So Saeyleenan oversees their trial in Moonglade, to teach them the spirit's nature.",sp=0}},faq={{q="Who is the Great Windborne Cat Spirit?",a="The windborne cat spirit appears as the Avatar of Saeyleenan, from distant Zephras. It has come to Moonglade to mentor and test young shen'dorei druids seeking its feline shape.",al={"who is the windborne cat spirit","what is avatar of saeyleenan","saeyleenan lore"}},{q="Where can the Avatar of Saeyleenan be found?",a="The Avatar of Saeyleenan appears in southern Moonglade, just south of the twin bridges.",al={"where to find cat spirit moonglade","avatar of saeyleenan location","windborne cat location"}},{q="Why do Zephras druids commune with a different cat spirit?",a="Shen'dorei druids come from Zephras, so their feline shape reflects the windborne spirits of their homeland rather than Azeroth's native big cats. The spirit oversees their trial to ensure they embody its essence.",al={"why does cat form look different","zephras cat form difference","why not azeroth cat spirit"}},{q="What does the trial of the windborne cat entail?",a="The Avatar of Saeyleenan has the initiate undertake the trial of Azeroth's Great Cat Spirit. The Avatar supervises and confirms that the druid understands the windborne spirit's unique nature.",al={"what trial does the cat spirit give","cat spirit trial zephras","how to get windborne cat form"}},{q="What does shen'dorei refer to?",a="The Avatar of Saeyleenan calls the initiate shen'dorei, marking their origin in Zephras and distinguishing their heritage and spiritual practices from Azeroth's native peoples.",al={"who are shendorei","shen dorei druids","what does shendorei mean"}},{q="What is Zephras?",a="Zephras is the distant homeland of the shen'dorei. Its native flora, fauna, and spirits differ from Azeroth's, giving rise to unique shapeshifting forms among its druids.",al={"what is zephras","where is zephras located","zephras homeland"}}},ang={["class:Druid"]="As a druid from Zephras, you commune with the windborne cat spirit to master your feline form. The rite follows your heritage rather than Azeroth's traditional path.",["race:Skyborne"]="As a Skyborne, you are called shen'dorei. The spirits of your homeland, Zephras, guide your druidic path."},kw={"cat form","cat spirit","druid trial","moonglade","saeyleenan","shen'dorei","windborne cat","zephras"},rel={"quest:98393","quest:5921"},m={faction="Horde",cl={"DRUID"},id=98341},src={"In-game quest text: The Great Windborne Cat Spirit"},fv=true}
E["quest:98362"] = {t="quest",n="To Thunder Bluff",z="moonglade",s="Back in Thunder Bluff, a young tauren druid returns in triumph after communion in Moonglade. The Great Cat Spirit has favored the initiate, who now seeks Turak Runetotem on the Elder Rise to master feline shapeshifting.",h="Back in Thunder Bluff, a young tauren druid returns in triumph after communion in Moonglade.",sec={{t="Return from Moonglade",b="You return to Mulgore after meeting dendrite starblaze and the great cat spirit in Moonglade's sacred groves. The communion joins ancient night elven teachings with the tauren's earthen heritage. It marks a pivotal milestone in a druid's training.",sp=0},{t="Mastering the Cat Form",b="Turak Runetotem awaits you atop the Elder Rise in Thunder Bluff. dendrite starblaze guided your communion with the great cat spirit, and Turak now teaches the physical change. With the spirit's blessing acknowledged, the elder trainer shows you how to take the cat's swift, predatory shape.",sp=0}},faq={{q="Where does this quest begin and end?",a="Dendrite Starblaze gives you this charge in Moonglade's sacred haven. You return to the Elder Rise in Thunder Bluff to speak with Turak Runetotem.",al={"where do i turn this in","who starts to thunder bluff","to thunder bluff quest turn in"},gp=true},{q="What is the purpose of this quest?",a="After earning the Great Cat Spirit's blessing in Moonglade, you return to your mentor in Thunder Bluff to learn cat form.",al={"why do to thunder bluff","what do i get from to thunder bluff","cat form quest"},it="purpose"},{q="Who is Turak Runetotem?",a="Turak Runetotem is a respected elder of the tauren druids on Thunder Bluff's Elder Rise. He oversees the training and initiation of young Horde druids who seek harmony with nature and mastery of their shapeshifting forms.",al={"turak runetotem lore","who is turak"},it="identity"},{q="Who is Dendrite Starblaze?",a="Dendrite Starblaze is a night elf keeper of the Cenarion Circle who guides visiting druids in Nighthaven, Moonglade. He bridges instruction between ancient kaldorei traditions and tauren practitioners despite factional tensions.",al={"dendrite starblaze role","night elf in moonglade"},it="identity"},{q="What is the Great Cat Spirit?",a="The Great Cat Spirit is an ancient primal being revered by druids. It embodies predatory instinct, stealth, and agility. Druids who seek cat form must pass a trial to earn its blessing and learn its playful and deadly nature.",al={"cat spirit lore","spirit of the cat"},it="power"},{q="Do Alliance druids have an equivalent task?",a="Yes. Night elf druids undergo a parallel rite in Moonglade, then return to Darnassus to report to their own mentor instead of traveling to the wind-swept mesas of Mulgore.",al={"alliance version of to thunder bluff","night elf cat form return"},gp=true},{q="Why does Dendrite Starblaze send you back to Thunder Bluff?",a="Dendrite Starblaze serves as a mentor and proctor in Moonglade, guiding you through communing with the Great Cat Spirit. With that trial completed and the spirit's favor earned, his role in this stage of your training is finished. He sends you back to Turak Runetotem so your primary instructor can impart the final teachings and guide you in actually adopting the cat form.",al={"why send to thunder bluff","dendrite starblaze motive","why return to turak runetotem"},it="motive",add="cdfa9758"}},ang={["class:Druid"]="As a druid, you learn from Turak Runetotem to master stealth and claws through this rite.",["race:Tauren"]="As a tauren, your journey reconnects you with Cenarion traditions as you carry lessons from Moonglade back to the Elder Rise of Thunder Bluff.",["faction:Horde"]="As a Horde druid, you return to your capital so your growing power can defend your kin. The Cenarion Circle remains neutral."},kw={"cat form","dendrite starblaze","druid","elder rise","great cat spirit","moonglade","thunder bluff","turak runetotem"},rel={"npc:turak-runetotem","npc:dendrite-starblaze","subzone:elder-rise","zone:thunderbluff","topic:druid","quest:1067"},m={start="Dendrite Starblaze",["end"]="Turak Runetotem",level="20",faction="Horde",cl={"DRUID"},id=98362},src={"To Thunder Bluff"},fv=true}
E["quest:98394"] = {t="quest",n="The Great Cat Spirit",z="moonglade",s="A wise spirit in southern Moonglade teaches druids about the cat’s nature. Its wisdom guides those who seek the feline shape.",h="A wise spirit in southern Moonglade teaches druids about the cat’s nature.",sec={{t="A Lesson in Moonglade",b="In southern Moonglade, the Great Cat Spirit waits on a hill above the bridge. Druids who seek the feline shape come to it for guidance. You are here to learn what it can teach about the nature of the cat.",sp=0}},faq={{q="Where is the Great Cat Spirit?",a="The Great Cat Spirit resides on a hill in southern Moonglade, overlooking the bridge.",al={"cat spirit location","where find cat spirit"}},{q="What does the Great Cat Spirit teach?",a="The Great Cat Spirit teaches druids about the nature of the cat and the feline shape.",al={"cat spirit teaches what","learn cat shape"}},{q="Why do druids seek the Great Cat Spirit?",a="Druids seeking the feline shape come to the Great Cat Spirit for wisdom and guidance.",al={"why see cat spirit","druid cat spirit"}},{q="Who is the Great Cat Spirit?",a="The Great Cat Spirit is a wise, cunning being in southern Moonglade who tutors druids seeking the feline shape.",al={"great cat spirit who","cat spirit"}}},ang={["class:Druid"]="As a druid seeking the feline shape, you come to the Great Cat Spirit in Moonglade for wisdom about the cat."},kw={"cat nature","cat spirit","druid","feline shape","great cat spirit","moonglade"},rel={"quest:5921","topic:druid","quest:5929"},m={faction="Alliance",id=98394},src={"In-game quest text: The Great Cat Spirit"},fv=true}
E["quest:98397"] = {t="quest",n="To Darnassus",z="moonglade",s="In Darnassus, you return to the Cenarion Enclave after your trial with the Great Cat Spirit. Having proved yourself to Dendrite Starblaze in Moonglade, you come to Mathrengyl Bearwalker to learn cat form.",h="In Darnassus, you return to the Cenarion Enclave after your trial with the Great Cat Spirit.",sec={{t="Return to the Enclave",b="You return to Teldrassil after meeting the Great Cat Spirit under Dendrite Starblaze's guidance in Moonglade. Starblaze has seen you prove yourself as a worthy student. So he sends you to your primary instructor, Mathrengyl Bearwalker. He waits beneath the boughs of the Cenarion Enclave in Darnassus.",sp=0},{t="The Nature of the Cat",b="In Darnassus, Mathrengyl Bearwalker sees the wisdom you gained from the Great Cat Spirit. Each generation of druids faces a trial shaped by this ancient spirit, playful yet deadly. Your bond is made, and your spirit is ready. Mathrengyl teaches you the final rites for taking cat form.",sp=0}},faq={{q="What is the purpose of this quest?",a="This is the final part of your trial with the Great Cat Spirit. After your time with Dendrite Starblaze in Moonglade, you return to Mathrengyl Bearwalker in Darnassus. He teaches you to take cat form.",al={"why do this quest","to darnassus purpose","cat form quest"},it="purpose"},{q="Who sends you back to Darnassus?",a="Dendrite Starblaze, a senior druid who lives in Nighthaven in Moonglade, sends you back after you receive the Great Cat Spirit's blessing.",al={"who starts this quest","quest giver"},it="identity"},{q="Where can I find Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker waits in the Cenarion Enclave, in Darnassus's northwestern quarter on Teldrassil.",al={"mathrengyl location","where is bearwalker"},it="target",gp=true},{q="What is the significance of the Great Cat Spirit?",a="The Great Cat Spirit is an ancient, feral spirit of nature, tied to agile and deadly predators. Druids must earn its favor and understand its playful yet lethal nature before they can channel its shape.",al={"cat spirit lore","what is Great Cat Spirit"},it="history"},{q="Do all druids complete the exact same trial?",a="Mathrengyl Bearwalker says every druid must pass a trial granted by the Great Cat Spirit to master its form. The trials vary across generations.",al={"are druid trials the same","generation trials"}},{q="Can non-night elves take this quest?",a="This path is for Alliance night elf druids returning to Darnassus. Tauren druids follow their own path and report to their trainers in Thunder Bluff after visiting Moonglade.",al={"is this alliance only","can tauren do this"},gp=true},{q="Why does Dendrite Starblaze send you back to Darnassus?",a="You have proved your worth before the Great Cat Spirit in Moonglade, and your trials under Dendrite Starblaze are complete. Dendrite's duty was to oversee your communion with the ancient spirit; now, your initial trainer, Mathrengyl Bearwalker, awaits your return in Darnassus to help you apply those spiritual lessons and finally master the shapeshifting art of the cat.",al={"why send to darnassus","dendrite starblaze motive","why return to mathrengyl"},it="motive",add="5fd4c60a"}},ang={["class:Druid"]="As a druid, cat form lets you channel the Great Cat Spirit directly.",["race:NightElf"]="As a night elf, your return to Darnassus honors the traditions the Cenarion Circle keeps beneath Teldrassil.",["faction:Alliance"]="As an Alliance druid, you return from neutral Moonglade to Darnassus, strengthening your homeland's magical defenses."},kw={"cat form","cenarion enclave","Dendrite Starblaze","Great Cat Spirit","mathrengyl bearwalker","moonglade","teldrassil","to darnassus"},rel={"npc:mathrengyl-bearwalker","npc:dendrite-starblaze","subzone:cenarion-enclave","zone:darnassus","topic:druid"},m={start="Dendrite Starblaze",["end"]="Mathrengyl Bearwalker",level="20",faction="Alliance",cl={"DRUID"},id=98397},src={"To Darnassus (Forever)"},fv=true}
E["quest:98404"] = {t="quest",n="The Great Windborne Cat Spirit",z="moonglade",s="At the Avatar of Saeyleenan, young druids face a trial of cunning and stealth. They enter the nearby Stormrage Barrow Den to recover three relics while avoiding enraged spirits. Passing the rite earns them the blessing to wield cat form.",h="At the Avatar of Saeyleenan, young druids face a trial of cunning and stealth.",sec={{t="The Trial of Cunning and Stealth",b="A seeker must show the nature of a predator before drawing upon the Great Windborne Cat Spirit. The cat calls for cunning and patience, then fierce action when cornered. The spirit tests those who seek its power, asking them to think, move, and strike like wild feline hunters. Only then may an initiate earn the right to take the cat's shape.",sp=0},{t="The Stormrage Barrow Den",b="The trial leads into the Stormrage Barrow Den, just east of the spirit's avatar. Three sacred tokens lie in its halls: the Relic of the Fang, the Relic of the Claw, and the Relic of the Silent Shadow.\n\nEnraged spirits have overrun the den and attack intruders on sight. A seeker cannot rely on brute force alone, but must tread carefully through the darkness to reach the relics.",sp=0},{t="The Avatar of Saeyleenan",b="The Avatar of Saeyleenan is the physical manifestation through which the Great Windborne Cat Spirit speaks to young initiates. Untutored seekers lack a seasoned predator's stealth, so a statue at the barrow den's entrance grants them temporary concealment.\n\nThose who slip past the frenzied spirits and return all three relics show they have learned the predator's ways. The Avatar recognizes their worthiness and grants the blessing to wield cat form.",sp=0}},faq={{q="Who is the Great Windborne Cat Spirit?",a="The Great Windborne Cat Spirit guides young druids in mastering feline shapeshifting. Through the Avatar of Saeyleenan, it embodies cunning, stealth, and ferocity. It tests aspirants before granting its form, to ensure they respect the cat's instincts and nature.",al={"windborne cat spirit","who is saeyleenan","cat spirit lore"}},{q="What is the Avatar of Saeyleenan?",a="The Avatar of Saeyleenan speaks for the Great Windborne Cat Spirit and stands west of the Stormrage Barrow Den. It assigns seekers to recover the stolen or hidden relics, then evaluates whether each initiate has shown enough stealth and cunning to earn the feline blessing.",al={"avatar of saeyleenan","who is avatar saeyleenan","saeyleenan npc"}},{q="What relics are required for the trial?",a="The trial calls for the Relic of the Fang, the Relic of the Claw, and the Relic of the Silent Shadow, all found in the Stormrage Barrow Den. Together, they symbolize the cat's physical weapons and elusive stealth, and prove an initiate's reverence for every aspect of the predator.",al={"three relics","relic of the claw","stormrage barrow den relics"}},{q="Where is the Stormrage Barrow Den located?",a="The Stormrage Barrow Den lies just east of the Avatar of Saeyleenan. Its subterranean chambers hold the three sacred relics and test the druids. Initiates must avoid the enraged spirits wandering its dark tunnels.",al={"stormrage barrow den location","where is barrow den","where to find relics"}},{q="Why are enraged spirits guarding the barrow den?",a="The Stormrage Barrow Den is overrun by powerful enraged spirits that attack living intruders on sight. They are hostile threats, not willing guardians. Their presence forces aspiring druids to use cunning and stealth to recover the relics instead of fighting them directly.",al={"why are spirits enraged","enraged spirits barrow den","barrow den guardians"}},{q="How do seekers sneak past the enraged spirits?",a="A stone statue at the Stormrage Barrow Den's entrance grants seekers a temporary blessing of stealth. Young initiates have not yet earned their own cat form or prowling abilities, so the enchantment helps them pass the hostile spirits unseen and secure the relics.",al={"how to stealth barrow den","statue stealth buff","how to avoid enraged spirits"}},{q="What reward or blessing is granted upon completing the trial?",a="When the seeker returns the Relic of the Fang, the Relic of the Claw, and the Relic of the Silent Shadow, the Avatar of Saeyleenan deems them worthy of the Great Windborne Cat Spirit's blessing. The rite shows their understanding of the cat's nature and grants the spiritual approval needed to take the predator's shape.",al={"trial reward","what do you get from cat spirit","cat spirit blessing"}}},ang={["class:Druid"]="As a druid, you must show cunning and ferocity before the spirit grants its shapeshifting blessing. The rite teaches you to channel the wild cat's agility, stealth, and predatory instinct.",["race:NightElf"]="As a night elf, you can trace the Stormrage Barrow Den's name to one of the most prominent night elven druidic lineages. Its depths connect Kaldorei practitioners to their people's ancient barrow heritage and ancestral spirits."},kw={"avatar of saeyleenan","cat form","druid trial","enraged spirits","relic of the claw","relic of the fang","relic of the silent shadow","saeyleenan","stormrage barrow den","the great windborne cat spirit"},rel={"topic:druid"},m={faction="Horde",cl={"DRUID"},id=98404},src={"In-game quest text: The Great Windborne Cat Spirit"},fv=true}
E["quest:98405"] = {t="quest",n="The Great Cat Spirit",z="moonglade",s="A wise spirit in southern Moonglade teaches druids who seek the cat shape. You go to learn what it knows of the feline form.",h="A wise spirit in southern Moonglade teaches druids who seek the cat shape.",sec={{t="A Druid's Teacher",b="Druids who seek the feline shape look to the Great Cat Spirit in southern Moonglade. It lives on a hill overlooking the bridge, where it offers wisdom to those who come to learn. You seek its teaching about the nature of the cat.",sp=0}},faq={{q="Where is the Great Cat Spirit?",a="The Great Cat Spirit lives on a hill in southern Moonglade overlooking the bridge.",al={"cat spirit location","where cat spirit","great cat spirit moonglade"}},{q="What does the Great Cat Spirit teach?",a="The Great Cat Spirit teaches druids about the nature of the cat and the feline shape.",al={"cat spirit teaches what","learn cat form","cat shape teacher"}},{q="Why do druids seek the Great Cat Spirit?",a="Druids who desire the feline shape seek the Great Cat Spirit's wisdom and instruction.",al={"why cat spirit","druid cat spirit","cat form wisdom"}}},ang={["class:Druid"]="As a druid, you seek the Great Cat Spirit's wisdom if you desire to take the feline shape."},kw={"cat shape","cat spirit","druid","feline form","great cat spirit","moonglade"},rel={"quest:5921","topic:druid","quest:5929"},m={faction="Horde",id=98405},src={"In-game quest text: The Great Cat Spirit"},fv=true}
E["quest:98731"] = {t="quest",n="Blessings of the Great Cat Spirit",z="moonglade",s="After the Great Cat Spirit’s blessing, you are told to return to Dendrite. He senses new cunning and ferocity in you, and says you can now learn to call upon the cat’s spirit.",h="After the Great Cat Spirit’s blessing, you are told to return to Dendrite.",sec={{t="Dendrite’s Reading",b="Dendrite greets you with a gesture in the air, and an aura of power comes over him. He senses the cat’s cunning and ferocity in you, along with a new understanding of stealth and speed. Now he can teach you to focus that nature and call upon the cat’s spirit.",sp=0}},faq={{q="Why does Dendrite want to see me?",a="After the Great Cat Spirit’s blessing, you are told to return to Dendrite, who will instruct you further.",al={"why return to Dendrite","Dendrite cat blessing","what does Dendrite want"}},{q="What does Dendrite sense in me?",a="He senses the cat’s cunning and ferocity, and believes you understand the stealth and speed needed to adopt its nature.",al={"what changed in me","cat spirit power","Dendrite senses what"}},{q="What can I learn from Dendrite now?",a="Dendrite says you can learn to focus your cunning and call upon the cat’s spirit.",al={"call cat spirit","learn cat nature","what next with Dendrite"}}},kw={"blessing","cat spirit","cunning","dendrite","ferocity","great cat spirit","speed","stealth"},rel={"quest:98393"},m={faction="Alliance",id=98731},src={"In-game quest text: Blessings of the Great Cat Spirit"},fv=true}
E["quest:98738"] = {t="quest",n="Blessings of the Great Windborne Cat Spirit",z="moonglade",s="After meeting the Great Cat Spirit of Zephras, an initiate returns to Dendrite with a newly awakened aura. The blessing brings the wild cat's stealth, speed, and ferocity, and Dendrite prepares the initiate for further instruction.",h="After meeting the Great Cat Spirit of Zephras, an initiate returns to Dendrite with a newly awakened aura.",sec={{t="Communion with the Windborne Spirit",b="An initiate returns to Dendrite after seeking the Great Cat Spirit of Zephras and earning its favor. The communion has awakened the wild cat's cunning, predatory stealth, and ferocity within them.",sp=0},{t="Dendrite's Instruction",b="Dendrite reads the initiate's newly awakened aura with subtle gestures. Sensing feline instincts woven into their spirit, he sees that the initiate is ready to focus their mind and call upon the true aspect of the cat.",sp=0}},faq={{q="What is Blessings of the Great Windborne Cat Spirit?",a="An initiate who has received the Great Cat Spirit's blessing returns to Dendrite to continue their spiritual communion.",al={"what is this quest","blessings of the cat quest","cat spirit quest"}},{q="Who is Dendrite?",a="Dendrite mentors initiates and sends them to commune with the Great Cat Spirit. When they return, his ritual gestures let him sense whether they have absorbed the stealth, speed, and cunning needed to channel feline nature.",al={"who is dendrite","dendrite lore"}},{q="Who is the Great Cat Spirit?",a="The Great Cat Spirit is an ancient patron in Zephras. It grants worthy initiates spiritual favor, the speed of the winds, and predatory stealth before they return to their instruction.",al={"what is the cat spirit","great windborne cat spirit"}},{q="Where is Zephras located?",a="Zephras is the Great Cat Spirit's home. Promising initiates travel there to seek its counsel, receive its blessings of wind and shadow, and learn the foundations of the feline form.",al={"where is zephras","cat spirit location"}},{q="Why does the spirit address the initiate as shen'dorei?",a="The Great Cat Spirit addresses the initiate as young shen'dorei, recognizing the practitioner's ancestral heritage as they seek communion with nature spirits and mastery of feral shapeshifting.",al={"who are shendorei","young shendorei"}},{q="What does the blessing of the cat spirit grant?",a="The blessing grants the cunning, speed, and stealth of the feline form. It also earns the initiate Dendrite's recognition, so they can focus their inner ferocity and call upon the true nature of the cat.",al={"what does the blessing give","cat spirit blessing effect"}}},ang={["class:Druid"]="For a druid, this rite marks a milestone in mastering feline predatory instinct. It grants the stealth, speed, and ferocity needed to commune with and assume the aspect of the cat.",["race:Skyborne"]="As a Skyborne, the Great Cat Spirit recognizes you as young shen'dorei. Its guidance from Zephras teaches you to harness feral power through wind and shadow."},kw={"blessings of the great windborne cat spirit","cat form","dendrite","druid","great cat spirit","shen'dorei","stealth","zephras"},rel={"quest:98393"},m={faction="Horde",cl={"DRUID"},id=98738},src={"In-game quest text: Blessings of the Great Windborne Cat Spirit"},fv=true}
E["quest:98739"] = {t="quest",n="Blessings of the Great Cat Spirit",z="moonglade",s="Dendrite asks you to return after receiving the Great Cat Spirit’s blessing. He senses a new cunning and ferocity in you, and says you can now learn to call upon the cat’s spirit.",h="Dendrite asks you to return after receiving the Great Cat Spirit’s blessing.",sec={{t="Return to Dendrite",b="After the Great Cat Spirit’s blessing, Dendrite asks you to return to him. When you arrive, he gestures above you and senses the cat’s cunning and ferocity in your eyes. He says you now understand the stealth and speed needed to take on this nature.",sp=0}},faq={{q="Who do I speak to?",a="Return to Dendrite and speak with him.",al={"who do i talk to","speak to who"}},{q="What blessing did I receive?",a="You have received the blessing of the Great Cat Spirit.",al={"great cat blessing","cat spirit blessing"}},{q="What does Dendrite sense in me?",a="Dendrite senses the cat’s cunning and ferocity in you, along with an understanding of its stealth and speed.",al={"what does dendrite see","cat nature"}},{q="What can I learn now?",a="Dendrite says you can now learn to focus your cunning and call upon the cat’s spirit.",al={"call cat spirit","what now"}}},kw={"blessing","blessings of the great cat spirit","cunning","dendrite","ferocity","great cat spirit","speed","stealth"},rel={"quest:98393"},m={faction="Horde",id=98739},src={"In-game quest text: Blessings of the Great Cat Spirit"},fv=true}
E["subzone:lake-elune-ara"] = {t="subzone",n="Lake Elune'ara",z="moonglade",s="At Moonglade's heart, Lake Elune'ara rests beneath moonlit groves. The sacred waters honor Elune, and the Cenarion Circle's shrine grounds border its shores.",h="At Moonglade's heart, Lake Elune'ara rests beneath moonlit groves.",sec={{t="Heart of the Sacred Vale",b="Moonlit groves frame Lake Elune'ara, whose waters are said to bear the White Lady's blessing. Nighthaven lies to the north, and the Cenarion Circle's shrine grounds border the lake. Initiates have long searched its depths for lost relics. Through contact with nature's currents, they seek harmony with the land.",sp=0},{t="The Slumber of Omen",b="Ancient peril sleeps beneath Lake Elune'ara's quiet surface. Legends tell of Omen, a two-headed wolf demigod and revered ancient corrupted by the Burning Legion during the War of the Ancients. Defeated long ago, Omen was cast into the lake bed. There he sleeps beneath the dark water, a reminder of nature's wounds.",sp=0}},faq={{q="What is Lake Elune'ara?",a="Night elves and druids revere Lake Elune'ara's sacred waters at the heart of Moonglade. Its name honors the Moon Goddess Elune, and the Cenarion Circle's sanctuaries surround it.",al={"lake eluneara","moonglade lake","where is lake eluneara"}},{q="What lurks at the bottom of the lake?",a="Omen, a fallen demigod, sleeps in the lake's dark depths. Once a noble ancient, he was driven mad by the Burning Legion during the ancient war and cast into the lake after his defeat.",al={"what is inside lake elune'ara","omen in moonglade","monster in lake"}},{q="Why do druids come to this lake?",a="Druids come to the lake for trials and to commune with the spirits of nature. Young druids search its waters for sacred relics as part of their rites of passage.",al={"druid quest lake","aquatic form lake"}}},ang={["class:Druid"]="As a druid, you know Lake Elune'ara as a place for rituals and trials. Sacred relics in its deep waters aid initiates on their path.",["race:NightElf"]="As a night elf, you know Lake Elune'ara by its name, which honors Elune. The lake is a place of divine peace and recalls the War of the Ancients."},kw={"cenarion circle","dark waters","elune","lake elune'ara","moonglade","nighthaven","omen"},rel={"zone:moonglade","topic:druid","topic:elune","quest:31","topic:emerald-dream","quest:5921"},src={"Lake Elune'ara"}}
E["subzone:nighthaven"] = {t="subzone",n="Nighthaven",z="moonglade",s="Nighthaven welcomes druids of both factions to Moonglade’s northern shore. Night elves and tauren study together in peace at the Cenarion Circle’s heart.",h="Nighthaven welcomes druids of both factions to Moonglade’s northern shore.",sec={{t="A Sanctuary of the Cenarion Circle",b="Along Lake Elune'ara’s calm northern shore, Nighthaven gathers night elf halls and moonwells among its groves. The Cenarion Circle keeps this secluded village as a place for druids to learn and tend to nature. Trainers, herbalists, and suppliers serve those who come to study. Here, druids find neutral ground whatever their ties to the Alliance or the Horde.",sp=0},{t="Ancient History and Sacred Gatherings",b="Peace in Nighthaven has faced a trial. Centuries after the War of the Ancients, champions gathered there to face the enraged demigod Omen. They drove him beneath Lake Elune'ara. During the Lunar Festival, the village opens its borders to pilgrims from across Azeroth, who honor the ancestors beneath Elune's watchful gaze.",sp=0}},faq={{q="Who rules or oversees Nighthaven?",a="The Cenarion Circle oversees Nighthaven, guided by Keeper Remulos and senior druids such as Loganaar. The village is an independent, neutral sanctuary, outside the night elven government’s rule.",al={"who runs nighthaven","nighthaven leaders","who is in charge here"}},{q="Can non-druids visit Nighthaven?",a="Yes. Non-druids can reach Moonglade through the Timbermaw tunnels or by taking a public flight to elsewhere in the valley, then travel to Nighthaven. The village’s own flight masters serve druids only.",al={"can non druids go to nighthaven","how do non druids get here"}},{q="Why are night elves and tauren living together peacefully here?",a="Night elves and tauren live peacefully in Nighthaven because the Cenarion Circle places healing nature and the Emerald Dream above faction politics. Its members vow to remain neutral in Moonglade and study druidism as equals, setting aside Alliance and Horde rivalries.",al={"why no fighting here","why are tauren allowed here","horde alliance peace"}},{q="What flight routes are available from Nighthaven?",a="Druids can take direct routes with Nighthaven’s Cenarion flight masters. Alliance druids can fly by hippogryph to Rut'theran Village, while Horde druids can ride wind riders to Thunder Bluff.",al={"nighthaven flight masters","where can i fly from here"}}},ang={["class:Druid"]="As a druid, you find your spiritual home in Moonglade at Nighthaven. Teleport: Moonglade brings you to your order's mentors, animal form trials, and flight connections to Rut'theran Village or Thunder Bluff.",["profession:Herbalism"]="As an herbalist, you can consult herbalism trainers among Nighthaven's tranquil groves in Moonglade."},kw={"cenarion circle","druid","lake elune'ara","loganaar","lunar festival","moonglade","nighthaven","remulos"},rel={"zone:moonglade","topic:cenarion-circle","subzone:lake-elune-ara","npc:remulos","npc:loganaar","topic:druid","subzone:rut-theran-village","zone:thunderbluff"},src={"Nighthaven"}}
E["subzone:stormrage-barrow-dens"] = {t="subzone",n="Stormrage Barrow Dens",z="moonglade",s="Beneath Moonglade, druids sleep in the Stormrage Barrow Dens. Their bodies rest here while their spirits journey through the Emerald Dream.",h="Beneath Moonglade, druids sleep in the Stormrage Barrow Dens.",sec={{t="Chambers of the Slumbering",b="Beneath Moonglade, the Stormrage Barrow Dens hold druids in deep sleep. Barrow dens across night elven lands guard their bodies while their spirits journey through the Emerald Dream. These earthen halls bear the name of Archdruid Malfurion Stormrage. Clintar Dreamwalker still sleeps in one of their alcoves. Malfurion is absent, and his brethren keep watch over the quiet chambers.",sp=0},{t="Echoes of the Third War",b="The Stormrage Barrow Dens nearly fell during the Third War. Tichondrius and the Burning Legion sought to destroy the sleeping druids before they could rally. High Priestess Tyrande Whisperwind fought demons and corrupted wildlife in the tunnels, then sounded the Horn of Cenarius. The call woke Malfurion Stormrage in time. After Archimonde fell at Mount Hyjal, Malfurion's spirit returned to the Emerald Dream. His brethren still watch over the dens.",sp=0}},faq={{q="What is the purpose of the Stormrage Barrow Dens?",a="Barrow dens shelter night elf druids while they journey through the Emerald Dream. Their bodies lie still and unguarded for months or years, so their brethren keep watch over these quiet underground sanctuaries.",al={"what are the barrow dens for","why sleep in barrow dens","stormrage barrow dens purpose"}},{q="Is Malfurion Stormrage currently inside these dens?",a="Malfurion Stormrage is absent from the dens. He slept there during the Third War, until Tyrande awakened him. Since the war, his spirit has been lost in the Emerald Dream, and the Cenarion Circle carries on without him.",al={"where is malfurion","is malfurion in the barrow dens","can i find malfurion here"}},{q="Who is currently sleeping within these dens?",a="Clintar Dreamwalker is among the druids sleeping in the dens. His body rests beneath the earth while his spirit journeys through nature's pathways.",al={"who is asleep here","clintar dreamwalker","sleeping druids moonglade"}},{q="What happened to this place during the Third War?",a="During the Third War, Tichondrius and the Burning Legion invaded the dens to kill the sleeping night elf druids. High Priestess Tyrande Whisperwind fought through the demons and sounded the Horn of Cenarius, waking Malfurion.",al={"third war barrow dens","tichondrius attack moonglade","tyrande awakening of stormrage"}}},ang={["class:Druid"]="As a druid, you see the Stormrage Barrow Dens as a heart of Cenarion heritage. Elder druids shelter their bodies in the earth while their spirits journey through the Emerald Dream.",["race:NightElf"]="As a night elf, you remember the long watch over the sleeping druids and Tyrande Whisperwind's perilous descent to awaken Malfurion against the Burning Legion."},kw={"barrow den","cenarion circle","clintar dreamwalker","emerald dream","malfurion","moonglade","stormrage barrow dens"},rel={"zone:moonglade","npc:malfurion-stormrage","topic:emerald-dream","topic:cenarion-circle","topic:druid","npc:tyrande-whisperwind","topic:third-war","topic:night-elf"},src={"Stormrage Barrow Dens"}}
E["subzone:timbermaw-hold"] = {t="subzone",n="Timbermaw Hold",z="moonglade",s="Within Timbermaw Hold, a furbolg tribe still resists demonic corruption. Its tunnels link Felwood, Moonglade, and Winterspring.",h="Within Timbermaw Hold, a furbolg tribe still resists demonic corruption.",sec={{t="A Sanctuary Amidst Decay",b="Deep beneath the mountain, the Timbermaw guard their home while corruption spreads through the forests above. During the Third War, the Burning Legion tainted neighboring furbolg tribes, but the Timbermaw endured in these stone corridors. From below, they watched their beloved forests warp. Now they distrust outsiders and defend every tunnel entrance, expecting violence from anyone coming in from the infected woods.",sp=0},{t="Crossroads of the North",b="Timbermaw Hold is the only direct passage through the mountain between Felwood, Moonglade, and Winterspring. Its sentries let outsiders pass only after they prove their goodwill. Those who oppose the corrupted furbolg clans may find steadfast allies among the Timbermaw. They share their ancient shamanic knowledge and leathercrafting traditions.",sp=0}},faq={{q="Why do the furbolgs in Timbermaw Hold attack visitors?",a="The Timbermaw distrust outsiders after seeing neighboring kin succumb to the Burning Legion’s corruption. They fear strangers may bring the taint into their home or be mistaken for feral, demonic furbolgs. So they attack until visitors prove peaceful intentions.",al={"why are timbermaw hostile","timbermaw attacking me","how to get timbermaw friendly"}},{q="Which zones does Timbermaw Hold connect?",a="Timbermaw Hold connects Felwood, Moonglade, and Winterspring. Its main cavern opens to northern Felwood in the southwest, Moonglade to the north, and Winterspring to the east. A walled-off gate also lies in northern Azshara.",al={"timbermaw hold tunnel destinations","where does timbermaw hold lead","timbermaw exits"}},{q="How did the Timbermaw survive the Legion's taint?",a="The Timbermaw sheltered deep in their mountain caverns while demonic fel energy withered Felwood’s forests. During the height of the demonic invasion, they sealed themselves inside the hold. This preserved their minds and sacred shamanic ways while neighboring clans fell to madness.",al={"why are timbermaw uncorrupted","timbermaw not corrupted"}},{q="What is the sealed wooden door inside the hold?",a="A round wooden barrier blocks a side cavern deeper in the tunnels. Its purpose is uncertain, though travelers think it may seal older tunnel complexes leading toward the Barrow Deeps or other ancient chambers beneath Mount Hyjal.",al={"blocked door in timbermaw hold","timbermaw hold locked gate"}}},ang={["class:Druid"]="As a druid, you can travel through the hold between your sacred sanctuary in Moonglade and wounded Felwood. Furbolg spirits there need cleansing.",["class:Shaman"]="As a shaman, you can see how the Timbermaw have kept their spiritual traditions and healing rituals uncorrupted despite the fel corruption outside their cave gates."},kw={"felwood","furbolg","moonglade","timbermaw","timbermaw hold","tunnel","winterspring"},rel={"topic:furbolg","zone:felwood","zone:winterspring","zone:moonglade","topic:burning-legion","zone:azshara","subzone:irontree-woods"},src={"Timbermaw Hold"}}
E["zone:moonglade"] = {t="zone",n="Moonglade",z="moonglade",s="In Moonglade, druids of the Cenarion Circle gather beneath an endless twilight. The valley in northern Kalimdor shelters night elf and tauren druids, while travelers on foot brave Timbermaw Hold to reach it.",h="In Moonglade, druids of the Cenarion Circle gather beneath an endless twilight.",sec={{t="Sacred Twilight",b="Moonglade lies among the mountains north of Felwood and Winterspring. Beneath Elune's moon, twilight lingers over Lake Elune'ara, at the heart of a valley sacred since kaldorei civilization began. The Burning Legion left the glade untouched in both its ancient invasions and the recent Third War, held back by Cenarius and his offspring. Keeper Remulos watches over Moonglade now, guarding nature's balance in a refuge where factional conflict has no place.",sp=0},{t="Seat of the Circle",b="Malfurion Stormrage founded the Cenarion Circle millennia ago, and Moonglade remains its headquarters. In lakeside Nighthaven, druids learn from ancient traditions. After the Third War, the Circle welcomed tauren into its ranks, following Archdruid Hamuul Runetotem's teachings. Here, Alliance and Horde loyalties are set aside. Armed sentries keep the peace, and members who turn to violence face swift justice.",sp=0},{t="The Barrow Dens and the Dream",b="South of Lake Elune'ara lie the Stormrage Barrow Dens. For thousands of years, elven druids slept in these underground hollows as their spirits crossed the Emerald Dream. Their bodies rested under constant watch. During the Third War, Tyrande Whisperwind sounded the Horn of Cenarius here and awakened Malfurion.\n\nThe dens remain tied to the Dream. Yet strange ripples now rise from their deep tunnels, and dark whispers trouble the Emerald realm.",sp=1}},faq={{q="How do non-druid travelers reach Moonglade?",a="On foot, you pass through Timbermaw Hold, a tunnel complex linking upper Felwood, Winterspring, and Moonglade, unless ritual magic brings you during seasonal events. Timbermaw furbolgs guard the passage fiercely, and outsiders must prove their goodwill to earn safe conduct.",al={"how to get to moonglade","getting to moonglade","moonglade entrance"}},{q="Why can Horde and Alliance walk together peacefully here?",a="The Cenarion Circle governs Moonglade, serving nature rather than politics. Moonglade Wardens throughout Nighthaven attack anyone who starts violence against those in good standing with the Circle.",al={"why is moonglade neutral","pvp in moonglade","can horde and alliance fight here"}},{q="What is the purpose of Nighthaven?",a="Nighthaven is Moonglade's main settlement, where the Cenarion Circle dwells and works. Trainers, caretakers, and sanctuaries give kaldorei and tauren druids places to confer about the health of Azeroth's wild lands.",al={"nighthaven purpose","what is nighthaven","town in moonglade"}},{q="Who rules Moonglade in Malfurion Stormrage's absence?",a="Keeper Remulos watches over Moonglade from the Shrine of Remulos while Malfurion Stormrage is absent. With senior Circle members such as Dendrite Starblaze, he tends the sacred grounds and directs efforts to heal the world.",al={"leader of moonglade","who leads cenarion circle","who is remulos"}},{q="What rests beneath the Stormrage Barrow Dens?",a="The Stormrage Barrow Dens are deep chambers where druids entered long communion with the Emerald Dream. Their deep wings still hold powerful conduits to the Dream, though recent disturbances suggest unsettling nightmares are stirring within.",al={"barrow dens lore","stormrage barrow dens purpose","where druids sleep"}},{q="Why do druids have special flight paths out of Nighthaven?",a="Silva Fil'naveth, the hippogryph master, and Bunthen Plainswind, the wind rider keeper, offer druids direct passage from Nighthaven to Rut'theran Village and Thunder Bluff. These routes help the order travel between its sacred grove and its racial homelands.",al={"nighthaven flight masters","druid flight master moonglade","free flights in moonglade"}}},ang={["class:Druid"]="As a druid, Moonglade is your sacred home and sanctuary. Your spiritual bond lets you teleport here from anywhere across Azeroth, consult masters like Dendrite Starblaze, commune with great spirits, and master forms such as aquatic form.",["race:Tauren"]="As a tauren, your place in the Cenarion Circle renews an ancient bond with Cenarius. Hamuul Runetotem championed your inclusion, which Moonglade honors despite the night elves' long seclusion.",["race:NightElf"]="As a night elf, Moonglade was your people's spiritual heartland for ten millennia and the resting place of your sleeping archdruids. Elune's enduring blessing sheltered it."},kw={"cenarion circle","dendrite starblaze","emerald dream","lake elune'ara","moonglade","nighthaven","remulos","stormrage barrow dens"},rel={"topic:cenarion-circle","topic:druid","npc:remulos","subzone:nighthaven","subzone:stormrage-barrow-dens","subzone:lake-elune-ara","topic:emerald-dream","subzone:timbermaw-hold"},src={"Moonglade"}}
